methods.onPlayerComputeDropZones:
public function onPlayerComputeDropZones($player, &$args)
{
  foreach ($args['zones'] as &$zone) {
    if ($zone['type'] == 'pasture') {
      $zone['capacity'] += 2;
    } elseif ($zone['type'] == 'stable') {
      $zone['capacity'] = max($zone['capacity'], 2);
      if (!isset($zone['constraints'])) {
        $zone['constraints'] = [SHEEP];
      }
    }
  }
}

