methods.addAdditionalGood:
public function addAdditionalGood($event)
{
  $player = $this->getPlayer();
  $sows = [];
  foreach ($event['sows'] as $sow) {
    // print_r($sow);
    $field = $sow['field'];
    if($field['x'] >= 0 && $field['x'] <= 10 && $field['y'] >= 0 && $field['y'] <= 6){
      if ($this->getPlayer()->board()->isAdjacentToType($field['x'],$field['y'],'roomWood')
        || $this->getPlayer()->board()->isAdjacentToType($field['x'],$field['y'],'roomClay')
      || $this->getPlayer()->board()->isAdjacentToType($field['x'],$field['y'],'roomStone')
      ) {
        $type = $sow['type'];
        $location = 'board';
        if ($type == GRAIN || $type == VEGETABLE){
            $ids = Meeples::createResourceInLocation(
              $type,
              $location,
              $field['pId'],
              $field['x'],
              $field['y'],
              $type == GRAIN ? 2 : 1
            );
            $sows[] = [
            'field' => $field,
            'crops' => Meeples::getMany($ids)->toArray(),
          ];
          }
      }
    }
  }
  if (empty($sows)) {
    return;
  }
  Notifications::sow($player, $sows, true);
}

