public function removeReed(&$args, $nb)
{
  foreach ($args['costs']['trades'] as &$trade) {
    if (isset($trade[REED])) {
      $trade[REED] -= $nb;
      if ($trade[REED] <= 0) {
        unset($trade[REED]);
      }
      $trade['sources'][] = $this->id;
    }
  }
}

