methods.onOpponentAfterExchange:
public function onOpponentAfterExchange($player, $event)
{
  $trades = $event['trades'];
  $exchanges = $event['exchanges'];
  $reeds = 0;
  foreach ($trades as $tradeIndex) {
    if (is_array($tradeIndex) && $tradeIndex['source'] == 'discard') {
      continue;
    }
    $exchange = $exchanges[$tradeIndex] ?? null;
    if ($exchange) {
      $issheep = $exchange['from'][SHEEP] ?? 0;
      $ispig = $exchange['from'][PIG] ?? 0;
      $iscattle = $exchange['from'][CATTLE] ?? 0;
      if ($issheep > 0 || $ispig > 0 || $iscattle > 0){
        $isfood = $exchange['to'][FOOD] ?? null;
        if ($isfood > 0)
          return $this->gainNode([FOOD => 1]);
      }
    }
  }
}

