methods.removeWood:
protected function removeWood(&$args, $nb)
{
  foreach ($args['costs']['trades'] as &$trade) {
    if (isset($trade[WOOD])) {
      $trade[WOOD] -= $nb;
      if ($trade[WOOD] <= 0) {
        unset($trade[WOOD]);
      }
