methods.onPlayerComputeCostsFencing:
  public function onPlayerComputeCostsFencing($player, &$args)
  {
    $baseline = $this->getExtraDatas('fences');
    if ($baseline === null) {
      $baseline = Fences::getOnBoard($player->getId())->count();
      $this->setExtraDatas('fences', $baseline);
    }

    // 只有尚未越过的第3/6/9/12/15根栅栏才能免费：
    // 若该阈值已达成（$needed <= 0），本次行动不再提供减免，避免重复触发
    foreach ([3, 6, 9, 12, 15] as $threshold) {
      $needed = $threshold - $baseline;
      if ($needed >= 1) {
        Utils::addBonus($args['costs'], [WOOD => -1], $this->id, false, ['minNumRooms' => $needed]);
      }
    }
  }

