methods.onPlayerAfterExchange:
  public function onPlayerAfterExchange($player, $event)
  {
    $trades = $event['trades'];
    $exchanges = $event['exchanges'];
    $eatedanimals = 0;
    foreach ($trades as $tradeIndex) {
      if (is_array($tradeIndex) && $tradeIndex['source'] == 'discard') {
        continue;
      }
      $exchange = $exchanges[$tradeIndex] ?? null;

      if ($exchange) {
        $issheep = $exchange['from'][SHEEP] ?? null;
        $ispig = $exchange['from'][PIG] ?? null;
        $iscattle = $exchange['from'][CATTLE] ?? null;
        
        if (!is_null($issheep)){
          $isfood = $exchange['to'][FOOD] ?? null;
          if (!is_null($isfood))
            $eatedanimals += 1;
        }
        if (!is_null($ispig)){
          $isfood = $exchange['to'][FOOD] ?? null;
          if (!is_null($isfood))
            $eatedanimals += 1;
        }
        if (!is_null($iscattle)){
          $isfood = $exchange['to'][FOOD] ?? null;
          if (!is_null($isfood))
            $eatedanimals += 1;
        }
      }
    }

    $flow = [];
    if ($eatedanimals > 0)
    {
      for ($i = 1; $i <= $eatedanimals; $i++)
        $flow[] = $this->moveResourcesToSpaceNode([FOOD => 1], $this->id, true);
      return [
        'type' => NODE_OR,
        'optional' => true,
        'childs' => $flow
      ];
    }
  }

