public function onBuy($player)
{
  $rooms = $player->board()->getRooms();
  $used = [];
  foreach ($rooms as $room) {
    $adj = [
      ['x' => $room['x'] - 1, 'y' => $room['y']],
      ['x' => $room['x'] + 1, 'y' => $room['y']],
      ['x' => $room['x'], 'y' => $room['y'] - 1],
      ['x' => $room['x'], 'y' => $room['y'] + 1],
    ];
    foreach ($adj as $pos) {
      $key = $pos['x'] . ',' . $pos['y'];
      if (!isset($used[$key]) && $player->board()->isFreeZone($pos['x'], $pos['y'])) {
        $used[$key] = true;
        $created = Meeples::createResourceInLocation(STONE, 'board', $player->getId(), $pos['x'], $pos['y'], 1);
        Notifications::accumulate(Meeples::getMany($created), true);
        break 2;
      }
    }
  }
  $currentTurn = Globals::getTurn();
  $foodTurns = [$currentTurn + 1, $currentTurn + 2, $currentTurn + 3];
  $this->setExtraDatas('foodTurns', $foodTurns);
  return null;
}

