methods.onPlayerAfterExchange:
  public function onPlayerAfterExchange($player, $event)
  {
    $trades = $event['trades'];
    $exchanges = $event['exchanges'];
    $grainConverted = 0;
    foreach ($trades as $tradeIndex) {
      if (is_array($tradeIndex) && $tradeIndex['source'] == 'discard') {
        continue;
      }
      $exchange = $exchanges[$tradeIndex] ?? null;
      if ($exchange) {
        $grain = $exchange['from'][GRAIN] ?? null;
        $food = $exchange['to'][FOOD] ?? null;
        if (!is_null($grain) && !is_null($food)) {
          $grainConverted += $grain;
        }
      }
    }

    if ($grainConverted <= 0) {
      return null;
    }

    $rooms = count($player->board()->getRooms());
    $foodOnCard = Meeples::getResourcesOnCard($this->id, null, FOOD)->count();
    $maxPlace = min($grainConverted, $rooms - $foodOnCard);
    if ($maxPlace <= 0) {
      return null;
    }

    $flow = [];
    for ($i = 1; $i <= $maxPlace; $i++) {
      $flow[] = $this->moveResourcesToSpaceNode([FOOD => 1], $this->id, true);
    }
    return [
      'type' => NODE_OR,
      'optional' => true,
      'childs' => $flow
    ];
  }

