methods.moveFoodFromFishing:
public function moveFoodFromFishing($max)
{
  $player = $this->getPlayer();
  for ($i = 0; $i < $max; $i++) {
    $food = Meeples::getResourcesOnCard('ActionFishing', null, FOOD)->first();
    if ($food == null) break;
    Meeples::DB()->update([
      'meeple_location' => $this->id,
    ], $food['id']);
    $food['location'] = $this->id;
    Notifications::placeMeeple([$food]);
  }
}

