methods.countCategory:
private function countCategory($player, $category)
{
  switch ($category) {
    case GRAIN:
      return $player->countReserveResource(GRAIN);
    case VEGETABLE:
      return $player->countReserveResource(VEGETABLE);
    case SHEEP:
    case PIG:
    case CATTLE:
      return $player->countAnimalsOnBoard()[$category];
    case 'field':
      return count($player->board()->getFields());
    case 'pasture':
      return count($player->board()->getPastures());
    case 'stable':
      return $player->board()->countFencedStables();
    default:
      return 0;
  }
}

methods.computeBonusScore:
public function computeBonusScore()
{
  $category = $this->getExtraDatas('category');
  if ($category == null) {
    return;
  }
  $player = $this->getPlayer();
  $myCount = $this->countCategory($player, $category);
  $maxCount = 0;
  foreach (Players::getAll() as $p) {
    $c = $this->countCategory($p, $category);
    if ($c > $maxCount) {
      $maxCount = $c;
    }
  }
  if ($myCount > 0 && $myCount >= $maxCount) {
    $this->addBonusScoringEntry(2);
  }
}

