methods.computeBonusScore:
public function computeBonusScore()
{
  $player = $this->getPlayer();
  $reed = $player->countReserveResource(REED);
  $reed += Meeples::getResourcesOnCard('board', $player->getId(), REED)->count();
  $score = 0;
  if ($reed >= 8) {
    $score = 4;
  } else if ($reed >= 6) {
    $score = 3;
  } else if ($reed >= 4) {
    $score = 2;
  } else if ($reed >= 1) {
    $score = 1;
  }
  if ($score > 0) {
    $this->addBonusScoringEntry($score);
  }
}

