          'method' => 'placeVegetable',
          'args' => ['turn' => $targetTurn, 'count' => $extra],
        ],
      ]
    );
  }
  return [
    'type' => NODE_XOR,
    'optional' => true,
    'childs' => $childs,
  ];
}

