methods.onPlayerAfterExchange:
public function onPlayerAfterExchange($player, $event)
{
  $trades = $event['trades'];
  $exchanges = $event['exchanges'];
  $grainToStore = 0;
  $vegToStore = 0;
  foreach ($trades as $tradeIndex) {
    if (is_array($tradeIndex) && $tradeIndex['source'] == 'discard') {
      continue;
    }
    $exchange = $exchanges[$tradeIndex] ?? null;
    if (!$exchange) continue;
    $isFood = $exchange['to'][FOOD] ?? 0;
    if ($isFood <= 0) continue;
    $grainToStore += $exchange['from'][GRAIN] ?? 0;
    $vegToStore += $exchange['from'][VEGETABLE] ?? 0;
  }
  $childs = [];
  if ($grainToStore > 0) {
    $childs[] = [
      'action' => SPECIAL_EFFECT,
      'optional' => true,
      'args' => [
        'cardId' => $this->id,
        'method' => 'storeCrop',
        'args' => [GRAIN, $grainToStore],
      ],
    ];
  }
  if ($vegToStore > 0) {
    $childs[] = [
      'action' => SPECIAL_EFFECT,
      'optional' => true,
      'args' => [
        'cardId' => $this->id,
        'method' => 'storeCrop',
        'args' => [VEGETABLE, $vegToStore],
      ],
    ];
  }
  if (empty($childs)) return null;
  return ['type' => NODE_SEQ, 'childs' => $childs];
}

