methods.onPlayerAfterSow:
public function onPlayerAfterSow($player, $event)
{
  $sows = $event['sows'] ?? [];
  if (empty($sows)) return null;
  $childs = [];
  foreach ($sows as $sow) {
    $type = $sow['type'];
    $onCard = Meeples::getResourcesOnCard($this->id, $player->getId(), $type);
    if ($onCard->count() == 0) continue;
    $field = $sow['field'];
    $location = ($field['type'] ?? '') == 'fieldCard' ? $field['id'] : 'board';
    $childs[] = [
      'action' => SPECIAL_EFFECT,
      'optional' => true,
      'args' => [
        'cardId' => $this->id,
        'method' => 'moveCropToField',
        'args' => [$type, $field, $location],
      ],
    ];
  }
  if (empty($childs)) return null;
  return ['type' => NODE_SEQ, 'childs' => $childs];
}

