    $plows = 1;
    $cost = $event['cost'] ?? [];
    $stones = $cost[STONE] ?? 0;
    if ($stones >= 1) {
      $plows = 2;
    }
    
    $flow = [
      'type' => NODE_SEQ,
      'optional' => true,
      'childs' => [],
    ];

    for ($i = 0; $i < $plows; $i++) {
      $flow['childs'][] = [
        'action' => PLOW,
        'args' => ['source' => $this->name, 'cardId' => $this->id],
        'pId' => $this->pId,
      ];
    }
    if (count($flow['childs']) > 0)
      return $flow;
  }

