    $affectedTurn = $this->getExtraDatas('affectedTurn');
    if ($affectedTurn != Globals::getTurn()) {
      return false;
    }

    if ($this->isPlayerEvent($event) && $event['type'] == 'AfterPlaceFarmer') {
      return true;
