function haveLeastFarmer($currentPlayer)
{
  $count = $currentPlayer->countFarmers();
  $c = 0;
  foreach (Players::getAll() as $player) {
    if ($player->getId() != $currentPlayer->getId()) {
      if ($player->countFarmers() > $count) {
