methods.checkResources:
  public function checkResources($cId)
  {
    // 获取行动格上的资源
    $resources = Meeples::getResourcesOnCard($cId);
    $counts = [
      WOOD => 0,
      CLAY => 0,
      REED => 0,
      STONE => 0,
    ];

    foreach ($resources as $res) {
      if (isset($counts[$res['type']])) {
        $counts[$res['type']]++;
      }
    }

    // 检查是否满足至少6木/5砖/4<REED>/3<STONE>
    return $counts[WOOD] >= 6 || $counts[CLAY] >= 5 || $counts[REED] >= 4 || $counts[STONE] >= 3;
  }

