methods.onPlayerEndWorkPhase:
  public function onPlayerEndWorkPhase($player)
  {
    $cards = ActionCards::getVisible($player);

    // 找到所有提供"生娃"和"扩建房屋"的行动格
    $targetCards = $cards->filter(function ($card) {
      $actionType = $card->getActionCardType();
      return strpos($actionType, 'WishChildren') !== false || 
             strpos($actionType, 'FarmExpansion') !== false;
    });

    // 检查这些行动格是否都被占用
    $allOccupied = true;
    foreach ($targetCards as $card) {
      $farmers = Farmers::getOnCard($card->getId());
      $guests = Guests::getOnCard($card->getId());
      if ($farmers->empty() && $guests->empty()) {
        $allOccupied = false;
        break;
      }
    }

    // 如果所有目标行动格都被占用，则执行"生娃"行动
    if ($allOccupied && !$targetCards->empty()) {
      if ($player->countFarmers() < 5)
        return [
          'action' => WISHCHILDREN,
          'args' => [
            'constraints' => ['freeRoom'],
            'insideHouse' => true,
          ],
        ];
    }

    return null;
  }

