    // 1人游戏 - 第13回合或之后
    // 2人游戏 - 第11回合或之后
    // 3人游戏 - 第9回合或之后
    // 4人游戏 - 第7回合或之后
    // 5人游戏 - 第4回合或之后
    $requiredTurns = [
      1 => 13,
      2 => 11,
      3 => 9,
      4 => 7,
      5 => 4,
    ];

    $requiredTurn = $requiredTurns[$playerCount] ?? 0;
    return $currentTurn >= $requiredTurn;
  }

methods.onPlayerEndWorkPhase:
  public function onPlayerEndWorkPhase($player)
  {
    // 获取所有可见行动格
    $cards = ActionCards::getVisible($player);

    // 获取当前玩家占用的行动格中最小的回合数
    $myMinTurn = PHP_INT_MAX;
    $otherPlayers = $player->getOtherPlayers();
    $allPlayers = Players::getAll();

    // 先找到当前玩家占用的行动格的最小回合数
    foreach ($cards as $card) {
      $cardTurn = $card->getTurn();
      if ($cardTurn == 0) {
        continue;
      }

      // 检查当前玩家是否占用了这个行动格
      $farmers = Farmers::getOnCard($card->getId());
      $guests = Guests::getOnCard($card->getId());

      $myFarmer = $farmers->filter(function ($farmer) use ($player) {
        return $farmer['pId'] == $player->getId();
      });
      $myGuest = $guests->filter(function ($guest) use ($player) {
        return $guest['pId'] == $player->getId();
      });

      if (!$myFarmer->empty() || !$myGuest->empty()) {
        $myMinTurn = min($myMinTurn, $cardTurn);
      }
    }

    // 检查其他玩家占用的行动格中是否有比当前玩家小的回合数
    $hasSmallerTurn = false;
    foreach ($cards as $card) {
      $cardTurn = $card->getTurn();
      if ($cardTurn == 0) {
        continue;
      }

      // 检查是否有其他玩家占用了这个行动格
      $farmers = Farmers::getOnCard($card->getId());
      $guests = Guests::getOnCard($card->getId());

      $otherFarmer = $farmers->filter(function ($farmer) use ($player) {
        return $farmer['pId'] != $player->getId();
      });
      $otherGuest = $guests->filter(function ($guest) use ($player) {
        return $guest['pId'] != $player->getId();
      });

      if ((!$otherFarmer->empty() || !$otherGuest->empty()) && $cardTurn < $myMinTurn) {
        $hasSmallerTurn = true;
        break;
      }
    }

    // 如果当前玩家没有占用任何行动格，或者没有其他玩家占用更小回合数的行动格，则获得1分
    if (!$hasSmallerTurn || $myMinTurn == PHP_INT_MAX) {
      return $this->gainNode([SCORE => 1]);
    }

    return null;
  }

