methods.has2x2Fields:
  protected function has2x2Fields($fields)
  {
    $fieldPositions = [];
    foreach ($fields as $field) {
      if ($field['type'] == 'field') { // 只考虑普通字段
        $fieldPositions[] = ['x' => $field['x'], 'y' => $field['y']];
      }
    }

    // 检查是否有四个相邻形成的 2x2 正方形
    // 对于每个字段，检查它下方、右方和右下方是否也有字段
    foreach ($fieldPositions as $pos) {
      $x = $pos['x'];
      $y = $pos['y'];

      // 检查右方(x+2,y)、下方(x,y+2)、右下方(x+2,y+2)是否都有字段
      $hasRight = $this->hasFieldAtPosition($fieldPositions, $x + 2, $y);
      $hasDown = $this->hasFieldAtPosition($fieldPositions, $x, $y + 2);
      $hasRightDown = $this->hasFieldAtPosition($fieldPositions, $x + 2, $y + 2);

      if ($hasRight && $hasDown && $hasRightDown) {
        return true;
      }
    }

    return false;
  }

methods.hasFieldAtPosition:
protected function hasFieldAtPosition($positions, $x, $y)
{
  foreach ($positions as $pos) {
    if ($pos['x'] == $x && $pos['y'] == $y) {
      return true;
    }
  }
  return false;
}

