  public function onOpponentComputeArgsPlaceFarmerRemoval($player)
  {
    // 检查对手玩家是否已经有家庭成员被派遣到任何行动格
    $cards = ActionCards::getVisible($player);
    $hasFarmersOnActionSpaces = false;

    foreach ($cards as $card) {
      $guests = Guests::getOnCard($card->getId(), $player->getId());
      if (count($guests) > 0) {
        $hasFarmersOnActionSpaces = true;
        break;
      }
      $farmers = Farmers::getOnCard($card->getId(), $player->getId());
      foreach ($farmers as $farmer) {
        if ($farmer['state'] == ADULT) {
          $hasFarmersOnActionSpaces = true;
          break;
        }
      }
    }

    // 如果对手玩家已经有家庭成员被派遣，则限制他们使用猪市场
    if ($hasFarmersOnActionSpaces) {
      return ActionCards::getVisible($player)
        ->filter(function ($card) {
          return $card->getActionCardType() == 'PigMarket';
        })
        ->getIds();
    }

    return [];
  }

