methods.actPlacePiles:
public function actPlacePiles($zones)
{
  $player = $this->getPlayer();
  $freeZones = $player->board()->getFreeZones();

  // Keep only valid and distinct free zones
  $valid = [];
  foreach ($zones as $zone) {
    if ($this->isInZones($freeZones, $zone['x'], $zone['y']) && !$this->isInZones($valid, $zone['x'], $zone['y'])) {
      $valid[] = ['x' => $zone['x'], 'y' => $zone['y']];
    }
  }
  if (empty($valid)) {
    return;
  }

  // Place 1 stone from the supply on each chosen space
  $meepleIds = [];
  foreach ($valid as $zone) {
    array_push($meepleIds, ...Meeples::createResourceInLocation(STONE, 'board', $player->getId(), $zone['x'], $zone['y']));
  }
  $this->setExtraDatas('zones', array_merge($this->getPileZones(), $valid));
  Notifications::placeMeeple(Meeples::getMany($meepleIds));
}

