methods.collectPiles:
public function collectPiles($used)
{
  $player = $this->getPlayer();
  $stones_ = [];
  foreach ($used as $zone) {
    $meeples = Meeples::getSelectQuery()
      ->wherePlayer($player->getId())
      ->where([['type', STONE], ['player_id', $player->getId()], ['x', $zone['x']], ['y', $zone['y']]])
      ->get();
    foreach ($meeples as $meeple) {
      // Meeples::DB()->delete($meeple['id']);
      $stones_[] = $meeple;
      Meeples::DB()->update(
      [
        'player_id' => $player->getId(),
        'meeple_location' => 'reserve',
      ],
      $meeple['id']
    );
    }
  }

  $zones = $this->getPileZones();
  Utils::filter($zones, function ($zone) use ($used) {
    return !$this->isInZones($used, $zone['x'], $zone['y']);
  });
  $this->setExtraDatas('zones', $zones);
  $this->ReceiveMeeples($stones_, 'Receive');
  // if (!empty($stones_)) {
  //   Notifications::silentKill($stones_);
  // }
}

methods.onPlayerComputeCostsConstruct:
public function onPlayerComputeCostsConstruct($player, &$args)
{
  $zones = $this->getPileZones();
  if (empty($zones)) {
    return;
  }

  $n = 0;
  foreach ($player->board()->getRooms() as $room) {
    if ($this->isInZones($zones, $room['x'], $room['y'])) {
      $n++;
    }
  }

  if ($n > 0) {
    // Payment for the rooms just built on piled zones: 1 discount per such room
    for ($i = 0; $i < $n; $i++) {
      Utils::addBonusChoices(
        $args['costs'],
        [[WOOD => -1], [CLAY => -1], [REED => -1], [STONE => -1]],
        $this->id,
        false
      );
    }
    return;
  }

  // Pre-construction checks: grant the potential discount of each piled space
  $i = 0;
  foreach ($zones as $zone) {
    $i++;
    Utils::addBonusChoices(
      $args['costs'],
      [[WOOD => -1], [CLAY => -1], [REED => -1], [STONE => -1]],
      $this->id,
      false,
      ['minNumRooms' => $i]
    );
  }
}

