public function onPlayerAfterExchange($player, $event)
{
  $trades = $event['trades'];
  $exchanges = $event['exchanges'];
  $foodToLose = 0;
  foreach ($trades as $tradeIndex) {
    if (is_array($tradeIndex) && $tradeIndex['source'] == 'discard') {
      continue;
    }
    $exchange = $exchanges[$tradeIndex] ?? null;
    if ($exchange) {
      $isVeg = $exchange['from'][VEGETABLE] ?? null;
      $isFood = $exchange['to'][FOOD] ?? null;
      if (!is_null($isVeg) && !is_null($isFood)) {
        $foodToLose++;
      }
    }
  }
  if ($foodToLose > 0) {
    return $this->payNode([FOOD => $foodToLose]);
  }
}

