methods.onPlayerStartOfWork:
  public function onPlayerStartOfWork($player, $event)
  {
    // 只考虑基础资源（不含动物）
    $resourceTypes = [WOOD, CLAY, REED, STONE];

    // 统计每个积累行动格上各类资源的数量，找出“单一资源最多”的数量
    $maxCount = 0;
    $counts = []; // resource type => 某行动格上该资源的最大数量
    foreach (ActionCards::getAccumulationSpaces() as $space) {
      foreach ($resourceTypes as $type) {
        $count = Meeples::getResourcesOnCard($space->getId(), null, $type)->count();
        if ($count > 0) {
          $counts[$type] = max($counts[$type] ?? 0, $count);
          $maxCount = max($maxCount, $count);
        }
      }
    }

    if ($maxCount == 0) {
      return null;
    }

    // 数量并列最多的所有资源类型都作为可选项，玩家从中选择1种
    $childs = [];
    foreach ($counts as $type => $count) {
      if ($count == $maxCount) {
        $childs[] = $this->payGainNode([FOOD => 1], [$type => 1]);
      }
    }

    return [
      'type' => NODE_XOR,
      'optional' => true,
      'childs' => $childs,
    ];
  }

