methods.computeBonusScore:
public function computeBonusScore()
{
  $player = $this->getPlayer();
  $sowableFields = $player->board()->getEmptyFields();
  Utils::filter($sowableFields, function ($field) {
    return $field['location'] == 'board' && ($this->getPlayer()->board()->isAdjacentToType($field['x'],$field['y'],'roomWood')
        || $this->getPlayer()->board()->isAdjacentToType($field['x'],$field['y'],'roomClay')
      || $this->getPlayer()->board()->isAdjacentToType($field['x'],$field['y'],'roomStone'));
  });
  $score = 0;
  $animals = Meeples::getBoardAnimals($this->pId);
  // print_r($animals);
  foreach($sowableFields as $field)
  {
    foreach($animals as $animal)
    {
      if ($animal['x'] == $field['x'] && $animal['y'] == $field['y'])
      {
        $score += 1;
        break;
      }
    }
    // print_r($field);
  }
  $this->addBonusScoringEntry($score);
}

methods.onPlayerComputeDropZones:
  public function onPlayerComputeDropZones($player, &$args)
  {
    $zones = $player->board()->getFreeZones();

    $capacity = count($zones);

    if ($capacity > 0) {
      $n = 0;
      foreach($zones as $zone)
      {
      $new_ = false;
      for($i=0;$i<count($args['zones']);$i++)
      {
        if ($args['zones'][$i]['locations'][0]['x'] == $zone['x'] && $args['zones'][$i]['locations'][0]['y'] == $zone['y'])
        {
          $args['zones'][$i]['constraints'][] = CATTLE;
          $args['zones'][$i]['capacity'] = 2;
          $new_ = true;
          break;
        }
      }
      if (!$new_)
      {
      $newZone = [
        'type' => 'G70_special',
        'capacity' => 2,
        'locations' => [],
        'constraints' => [CATTLE]
      ];
      $newZone['locations'][] = [
          'x' => $zone['x'],
          'y' => $zone['y'],
        ];
        
      $args['zones'][] = $newZone;
      $n++;
      if ($n >= 2)
        break;
    }
    
    }
  }
}

methods.onPlayerHarvestFieldPhase:
  public function onPlayerHarvestFieldPhase($player, $event = null)
  {
    $animals = $player->countAnimalsOnBoard();
    $animalTypes = 0;
    foreach ($animals as $type => $count) {
      if ($count > 0) {
        $animalTypes++;
      }
    }

    $numFields = 0;
    if ($animalTypes >= 3) {
      $numFields = 2;
    } elseif ($animalTypes >= 2) {
      $numFields = 1;
    }

    if ($numFields == 0) {
      return null;
    }

    $fields = $player->board()->getPlantedFields();
    if (count($fields) == 0) {
      return null;
    }

    $numFields = min($numFields, count($fields));

    return [
      'type' => NODE_SEQ,
      'optional' => true,
      'childs' => [
        [
          'action' => SPECIAL_EFFECT,
          'args' => [
            'cardId' => $this->id,
            'method' => 'addCropsToFields',
            'args' => [$numFields],
          ],
        ],
      ],
    ];
  }

methods.addCropsToFields:
  public function addCropsToFields($numFields)
  {
    $player = Players::getActive();
    $fields = $player->board()->getPlantedFields();
    $sows = [];
    $count = 0;

    foreach ($fields as $field) {
      if ($count >= $numFields) {
        break;
      }
      $type = $field['crops'][0]['type'];
      $location = $field['type'] == 'fieldCard' ? $field['id'] : 'board';

      $ids = Meeples::createResourceInLocation(
        $type,
        $location,
        $field['pId'],
        $field['x'],
        $field['y'],
        1
      );

      $sows[] = [
        'field' => $field['id'],
        'type' => $type,
        'crops' => Meeples::getMany($ids)->toArray(),
      ];
      $count++;
    }

    if (!empty($sows)) {
      Notifications::sow($player, $sows, true);
      Notifications::updateDropZones($player);
    }
  }

