methods.onPlayerAfterExchange:
public function onPlayerAfterExchange($player, $event)
{
  $trades = $event['trades'];
  $exchanges = $event['exchanges'];
  $reeds = 0;
  foreach ($trades as $tradeIndex) {
    if (is_array($tradeIndex) && $tradeIndex['source'] == 'discard') {
      continue;
    }
    $exchange = $exchanges[$tradeIndex] ?? null;
    if ($exchange) {
      $issheep = $exchange['from'][SHEEP] ?? 0;
      $ispig = $exchange['from'][PIG] ?? 0;
      $iscattle = $exchange['from'][CATTLE] ?? 0;
      if ($issheep > 0 || $ispig > 0 || $iscattle > 0){
        $isfood = $exchange['to'][FOOD] ?? null;
        if ($isfood > 0)
          $reeds += intdiv($issheep, 2) + $ispig + $iscattle; 
      }
    }
  }
  // print_r($eated);
  if ($reeds > 0)
    return [
    'action' => SPECIAL_EFFECT,
    'args' => [
                'cardId' => $this->id,
                'method' => 'accResoucce',
                'args' => [$reeds]
              ]
  ];
  // return $this->gainNode([FOOD => $eated]);
}

methods.onPlayerComputeCostsConstruct:
public function onPlayerComputeCostsConstruct($player, &$args)
{
  $all_trades = [];
  foreach ($args['costs']['trades'] as $trade) {
    if (isset($trade[REED])) {
      $reed = $trade[REED];
      for ($i = 1; $i <= $reed; $i++) {
        $newTrade = $trade;
        $newTrade[REED] = $reed - $i;
        if ($newTrade[REED] <= 0) {
          unset($newTrade[REED]);
        }
        $newTrade[REED_PELT] = $i;
        $newTrade['sources'][] = $this->id;
        $all_trades[] = $newTrade;
      }
    }
  }
  foreach($all_trades as $trade)
    $args['costs']['trades'][] = $trade;
}

methods.onPlayerComputeCostsRenovation:
public function onPlayerComputeCostsRenovation($player, &$args)
{
  $all_trades = [];
  foreach ($args['costs']['fees'] ?? [] as $fee) {
    $keys = array_diff(array_keys($fee), ['nb', 'max']);
    if (in_array(REED, $keys)) {
      $fee_reed = $fee[REED] ?? 0;
      for ($i = 1; $i <= $fee_reed; $i++)
      {
        $newFee = $fee;
        $newFee[REED_PELT] = $i;
        $newFee[REED] = $fee_reed - $i;
        if ($newFee[REED] <= 0)
          unset($newFee[REED]);
        $newFee['sources'][] = $this->id;
        $all_trades[] = $newFee;
      }
    }
  }
  foreach($all_trades as $fee)
  {
    Utils::addFees($args['costs'], $fee);
  }
}

