public function onPlayerAfterSow($player, $event)
{
  $turn = \AGR\Core\Globals::getTurn();
  if ($turn % 2 != 0) return null;
  $sows = $event['sows'] ?? [];
  if (empty($sows)) return null;
  $notifSows = [];
  foreach ($sows as $sow) {
    $field = $sow['field'];
    $type = $sow['type'];
    $location = ($field['type'] ?? '') == 'fieldCard' ? $field['id'] : 'board';
    $ids = \AGR\Managers\Meeples::createResourceInLocation(
      $type,
      $location,
      $field['pId'],
      $field['x'],
      $field['y'],
      1
    );
    $notifSows[] = ['field' => $field, 'type' => $type, 'crops' => \AGR\Managers\Meeples::getMany($ids)->toArray()];
  }
  if (!empty($notifSows)) {
    \AGR\Core\Notifications::sow($player, $notifSows, true);
  }
  return null;
}

