methods.onPlayerComputeDropZones:
  public function onPlayerComputeDropZones($player, &$args)
  {
    // $already_zones = $player->board()->getAnimalsDropZones();
    // print_r($already_zones);
    $zones = $player->board()->getFreeZones();
    // print_r($zones);
    $capacity = count($zones);

    if ($capacity > 0) {
      foreach($zones as $zone)
      {
      $new_ = false;
      for($i=0;$i<count($args['zones']);$i++)
      {
        if ($args['zones'][$i]['locations'][0]['x'] == $zone['x'] && $args['zones'][$i]['locations'][0]['y'] == $zone['y'])
        {
          $args['zones'][$i]['constraints'][] = SHEEP;
          $args['zones'][$i]['capacity'] = 2;
          $new_ = true;
          break;
        }
      }
      if (!$new_)
      {
      $newZone = [
        'type' => 'G70_special',
        'capacity' => 2,
        'locations' => [],
        'constraints' => [SHEEP]
      ];
      $newZone['locations'][] = [
          'x' => $zone['x'],
          'y' => $zone['y'],
        ];
        
      $args['zones'][] = $newZone;
      }
    }
    
    }
  }

