methods.onPlayerAfterReceive:
public function onPlayerAfterReceive($player, $event)
{
  $meeples = $event['meeples'] ?? [];
  $animals = [SHEEP, PIG, CATTLE];
  $hasAnimal = false;
  foreach ($meeples as $meeple) {
    if (in_array($meeple['type'], $animals)) {
      $hasAnimal = true;
      break;
    }
  }
  if (!$hasAnimal) return null;
  return $this->discardRoomCrops();
}

methods.onPlayerEndOfTurn:
public function onPlayerEndOfTurn($player, $event)
{
  $turn = Globals::getTurn();
  $harvestTurns = [6, 8, 10, 12];
  $onCard = Meeples::getResourcesOnCard($this->id, $player->getId());

  $animals = $player->countAnimalsOnBoard();
  $hasAnimal = false;
  foreach ($animals as $type => $count) {
    if ($count > 0) { $hasAnimal = true; break; }
  }

  if ($hasAnimal && $onCard->count() > 0) {
    return $this->discardRoomCrops();
  }

  if (in_array($turn, $harvestTurns) && $onCard->count() > 0) {
    return [
      'type' => NODE_SEQ,
      'optional' => true,
      'childs' => [
        [
          'action' => SPECIAL_EFFECT,
          'args' => [
            'cardId' => $this->id,
            'method' => 'harvestRoomCrops',
            'args' => [],
          ],
        ],
      ],
    ];
  }
  return null;
}

