methods.onPlayerStartOfTurn:
  public function onPlayerStartOfTurn($player, $event)
  {
    $turn = Globals::getTurn();
    $harvestTurns = [4, 7, 10, 14];
    if (in_array($turn, $harvestTurns)) {
      return null;
    }

    $players = Players::getAll();
    $scores = [];
    $totalScoreSum = 0;
    foreach ($players as $p) {
      $animals = $p->countAnimalsOnBoard();
      $sheepCount = $animals[SHEEP];
      $cattleCount = $animals[CATTLE];
      $score = $sheepCount + $cattleCount * 2;
      $scores[$p->getId()] = $score;
      $totalScoreSum += $score;
    }

    if ($totalScoreSum === 0) {
      return null;
    }

    $maxScore = max($scores);
    $topPlayers = [];
    foreach ($scores as $pId => $score) {
      if ($score === $maxScore) {
        $topPlayers[] = $pId;
      }
    }

    $cardOwnerId = $player->getId();
    
    if (count($topPlayers) === 1 && $topPlayers[0] === $cardOwnerId) {
      return $this->gainNode([GRAIN => 1]);
    }
    
    if (count($topPlayers) > 1 && in_array($cardOwnerId, $topPlayers)) {
      return $this->gainNode([GRAIN => 1]);
    }

    return null;
  }

