methods.hasValidSpace:
public function hasValidSpace()
{
  $board = $this->getPlayer()->board();
  $rooms = $board->getRooms();
  if (empty($rooms)) {
    return false;
  }

  $roomCoords = [];
  foreach ($rooms as $room) {
    $roomCoords[] = ['x' => $room['x'], 'y' => $room['y']];
  }

  for ($x = 1; $x <= 7; $x += 2) {
    for ($y = 1; $y <= 3; $y += 2) {
      $block = [
        ['x' => $x, 'y' => $y],
        ['x' => $x + 2, 'y' => $y],
        ['x' => $x, 'y' => $y + 2],
        ['x' => $x + 2, 'y' => $y + 2],
      ];
      $allFree = true;
      foreach ($block as $pos) {
        if (!$board->isFree($pos['x'], $pos['y'])) {
          $allFree = false;
          break;
        }
      }
      if (!$allFree) {
        continue;
      }

      $adjacentToRoom = false;
      foreach ($block as $pos) {
        foreach ($roomCoords as $room) {
          $dx = abs($pos['x'] - $room['x']);
          $dy = abs($pos['y'] - $room['y']);
          if (($dx == 2 && $dy == 0) || ($dx == 0 && $dy == 2)) {
            $adjacentToRoom = true;
            break 2;
          }
        }
      }
      if ($adjacentToRoom) {
        return true;
      }
    }
  }
  return false;
}

