public function onPlayerHarvestBreedingPhase($player, $event = null)
{
  $grainCount = $player->countReserveResource(GRAIN);
  $canBreed = $player->breedTypes();

  $extraAnimals = [];

  if (!empty($canBreed[SHEEP]) && $grainCount >= 0 && $grainCount <= 3) {
    $extraAnimals[] = SHEEP;
  }
  if (!empty($canBreed[PIG]) && $grainCount >= 4 && $grainCount <= 7) {
    $extraAnimals[] = PIG;
  }
  if (!empty($canBreed[CATTLE]) && $grainCount >= 8) {
    $extraAnimals[] = CATTLE;
  }

  if (empty($extraAnimals)) {
    return null;
  }

  $childs = [];
  foreach ($extraAnimals as $animal) {
    $childs[] = $this->gainNode([$animal => 1]);
  }

  return [
    'type' => NODE_SEQ,
    'childs' => $childs,
  ];
}

