methods.onPlayerAfterPlow:
public function onPlayerAfterPlow($player, $event)
{
  $field = $event['field'] ?? null;
  if ($field == null) return null;
  $x = $field['x'];
  $y = $field['y'];
  $board = $player->board();
  $hasAdjacent = false;
  $dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  foreach ($dirs as $dir) {
    $nx = $x + $dir[0];
    $ny = $y + $dir[1];
    if ($nx >= 0 && $ny >= 0 && isset($board->grid[$nx][$ny]) && $board->grid[$nx][$ny]['type'] == 'field') {
      $hasAdjacent = true;
      break;
    }
  }
  if (!$hasAdjacent) return null;
  if ($player->countReserveResource(VEGETABLE) < 1) return null;
  return [
    'action' => SPECIAL_EFFECT,
    'optional' => true,
    'args' => [
      'cardId' => $this->id,
      'method' => 'sowVegetable',
      'args' => [$x, $y],
    ],
  ];
}

methods.sowVegetable:
public function sowVegetable($x, $y)
{
  $player = $this->getPlayer();
  $seed = $player->getNextCropToSow(VEGETABLE);
  if ($seed == null) return;
  Meeples::moveToCoords($seed['id'], 'board', ['x' => $x, 'y' => $y]);
  $ids = Meeples::createResourceInLocation(VEGETABLE, 'board', $player->getId(), $x, $y, 1);
  $crops = [];
  if (!empty($ids)) {
    $meeples = Meeples::getMany($ids, false);
    if (!$meeples->empty()) {
      $crops = $meeples->toArray();
    }
  }
  $sows = [[
    'field' => ['x' => $x, 'y' => $y],
    'type' => VEGETABLE,
    'seed' => $seed,
    'crops' => $crops,
  ]];
  Notifications::sow($player, $sows);
  Notifications::updateDropZones($player);
}

