  $actionCardId = $event['actionCardId'] ?? null;
  if ($actionCardId != 'ActionWesternQuarry' && $actionCardId != 'ActionEasternQuarry') {
    return null;
  }
  $meeples = $event['meeples'] ?? [];
  $stoneCount = 0;
  foreach ($meeples as $meeple) {
    if ($meeple['type'] == STONE) {
      $stoneCount++;
    }
  }
  if ($stoneCount == 0) {
    return null;
  }
  return [
    'action' => SPECIAL_EFFECT,
    'optional' => true,
    'args' => [
      'cardId' => $this->id,
      'method' => 'storeStone',
      'args' => [$actionCardId],
