methods.storeStone:
public function storeStone($actionCardId)
{
  $player = $this->getPlayer();
  $stones = Meeples::getReserveResource($player->getId(), STONE);
  $stoneCount = $stones->count();
  if ($stoneCount == 0) return;
  $toReturn = $stoneCount - 1;
  $i = 0;
  foreach ($stones as $stone) {
    if ($i < $toReturn) {
      Meeples::DB()->update(['meeple_location' => $actionCardId], $stone['id']);
    } else {
      Meeples::DB()->update(['meeple_location' => $this->id], $stone['id']);
      $stone['location'] = $this->id;
      Notifications::accumulate([$stone], true);
    }
    $i++;
  }
}

