methods.reduceCosts:
  private function reduceCosts(&$args)
  {
      $resourcesOnCard = Meeples::getResourcesOnCard($this->id, null);

      if ($resourcesOnCard->empty()) {
          return;
      }

      // 用此卡上的1木替代支付1木：减少1木成本，同时要求支付1份WOOD_NL028（从卡上扣除）。
      // 使用 bonusChoices 机制可统一处理 trades / fee / fees 等不同成本结构，且每次行动只生效一次。
      // optional 必须为 true：卡牌描述是"可以"用，且不可用时不能把其它支付方案一并清空。
      Utils::addBonusChoices($args['costs'], [[WOOD => -1, WOOD_NL028 => 1]], $this->id, true);
  }

