methods.onPlayerStartOfTurn:
  public function onPlayerStartOfTurn($player, $event)
  {
    $allPlayers = Players::getAll();
    $minFood = PHP_INT_MAX;
    $playersWithMinFood = [];

    foreach ($allPlayers as $p) {
      $reserve = $p->getAllReserveResources();
      $food = $reserve[FOOD] ?? 0;
      if ($food < $minFood) {
        $minFood = $food;
        $playersWithMinFood = [$p->getId()];
      } else if ($food === $minFood) {
        $playersWithMinFood[] = $p->getId();
      }
    }

    if (count($playersWithMinFood) === 1) {
      $targetPId = $playersWithMinFood[0];
      return [
        'type' => \NODE_SEQ,
        'pId' => $this->pId,
        'childs' => [
          $this->gainNode([FOOD => 1], $targetPId),
        ],
      ];
    }

    if (count($playersWithMinFood) > 1) {
      $flow = [];
      foreach ($playersWithMinFood as $targetPId) {
        $targetPlayer = Players::get($targetPId);
        $flow[] = [
          'type' => \NODE_SEQ,
          'childs' => [
            $this->gainNode([FOOD => 1], $targetPId),
          ],
        ];
      }
      return [
        'type' => \NODE_XOR,
        'optional' => false,
        'pId' => $this->pId,
        'customDescription' => clienttranslate('选择一位<FOOD>最少的玩家获得1<FOOD>'),
        'childs' => $flow,
      ];
    }

    return null;
  }

