private function getStoreCandidate()
{
  // EndWorkPhase: people have already been placed. They are not "available".
  $locations = array_merge(['board'], ActionCards::getVisible()->getIds());
  return Farmers::getAllOfPlayer($this->pId)->filter(function ($farmer) use ($locations) {
    return in_array($farmer['state'], [ADULT, CHILD]) && in_array($farmer['location'], $locations, true);
  })->first();
