methods.onPlayerReturnHome:
public function onPlayerReturnHome($player, $event = null)
{
  $id = $this->getExtraDatas('reservedFarmer');
  if ($id === null) return null;
  $this->setExtraDatas('reservedFarmer', null);
  $farmer = Farmers::get($id);
  // Defer the physical move until the home assignment. This retains the
  // person's room coordinates and does not change end-of-work scoring.
  if ($farmer['pId'] != $this->pId) return null;
  if ($farmer['location'] !== 'board') {
    // Room cards may have assigned the initially reserved person elsewhere.
    // Choose a person actually housed in a room instead; Joy House adds none.
    $farmer = Farmers::getAllOfPlayer($this->pId)->filter(function ($f) {
      return $f['location'] === 'board' && in_array($f['state'], [ADULT, CHILD]);
    })->first();
    if ($farmer === null) return null;
    $id = $farmer['id'];
  }
  Meeples::moveToCoords($id, $this->id, [$farmer['x'], $farmer['y']]);
  Notifications::returnHomeSilent([Meeples::get($id)]);
  Notifications::updateDropZones($player);
  return null;
}

