methods.getPairs:
public function getPairs($ignoreResources = false)
{
  $player = $this->getPlayer();
  $visible = ActionCards::getVisible();
  $forbidden = $player->computeForbiddenCards();
  $pairs = [];
  foreach ($visible as $top) {
    $bottom = ActionSpaceLayout::below($top, $visible);
    if ($bottom === null || in_array($top->getId(), $forbidden, true) ||
        in_array($bottom->getId(), $forbidden, true)) continue;
    // The top may supply resources needed below. Recheck the bottom in its
    // own PlaceFarmer action after the top and its reactions have resolved.
    $exclusive = $bottom->getExtraDatas('exclusiveUse') ?? [];
    if ($exclusive != [] && $exclusive != $this->pId) continue;
    if ($top->canBePlayed($player, null, $ignoreResources) &&
        Farmers::getOnCard($bottom->getId())->empty() && Guests::getOnCard($bottom->getId())->empty()) {
      $pairs[$top->getId()] = $bottom->getId();
    }
  }
  return $pairs;
}

