methods.haveLeastFarmer:
function haveLeastFarmer($currentPlayer)
{
  $count = $currentPlayer->countFarmers();
  $c = 0;
  foreach (Players::getAll() as $player) {
    if ($player->getId() != $currentPlayer->getId()) {
      if ($player->countFarmers() > $count) {
        $c++;
      }
    }
  }
  return $c > 0 && $c + 1 == count(Players::getAll());
}

methods.onPlayerAfterExchange:
  public function onPlayerAfterExchange($player, $event)
  {
    $trades = $event['trades'];
    $exchanges = $event['exchanges'];
    $cattleCooked = 0;

    foreach ($trades as $tradeIndex) {
      if (is_array($tradeIndex) && $tradeIndex['source'] == 'discard') {
        continue;
      }

      $exchange = $exchanges[$tradeIndex] ?? null;
      if ($exchange) {
        $source = $exchange['source'] ?? null;
        if ($this->isCookingSource($source)) {
          $isCattle = $exchange['from'][CATTLE] ?? null;
          if (!is_null($isCattle)) {
            $isFood = $exchange['to'][FOOD] ?? null;
            if (!is_null($isFood)) {
              $cattleCooked += $isCattle;
            }
          }
        }
      }
    }

    if ($cattleCooked > 0) {
      return [
        'type' => NODE_SEQ,
        'childs' => [
          $this->gainNode([FOOD => $cattleCooked]),
          [
            'action' => SPECIAL_EFFECT,
            'args' => [
              'cardId' => $this->id,
              'method' => 'addVp',
              'args' => [$cattleCooked],
            ],
          ],
        ],
