methods.actConvertStable:
public function actConvertStable($zones)
{
  $player = $this->getPlayer();
  $stable = null;
  foreach ($player->board()->getStables() as $candidate) {
    if (!empty($candidate['state']) && $candidate['state'] != 0) {
      continue;
    }
    foreach ($zones as $zone) {
      if ($zone['x'] == $candidate['x'] && $zone['y'] == $candidate['y']) {
        $stable = $candidate;
        break 2;
      }
    }
  }

  if (is_null($stable)) {
    throw new \BgaVisibleSystemException('O20_EmergencyHousing : no built stable on the selected zone');
  }

  Stables::setValid($stable['id'], false);
  $this->setExtraDatas('stableId', $stable['id']);
  $this->setExtraDatas('x', $stable['x']);
  $this->setExtraDatas('y', $stable['y']);

  $player->board()->refresh();
  Notifications::updateDropZones($player);
  $player->forceReorganizeIfNeeded();
}

