methods.onPlayerComputeCardCosts:
public function onPlayerComputeCardCosts($player, &$args)
{
  if (!in_array($args['card']->getType(), [MAJOR, MINOR])) {
    return;
  }
  $buildingRes = [WOOD, CLAY, REED, STONE];
  $newTrades = [];
  foreach ($args['costs']['trades'] as $trade) {
    foreach ($buildingRes as $fromRes) {
      if (isset($trade[$fromRes]) && $trade[$fromRes] >= 1) {
        foreach ($buildingRes as $toRes) {
          if ($toRes == $fromRes) { continue; }
          $copy = $trade;
          $copy[$fromRes] -= 1;
          if ($copy[$fromRes] <= 0) { unset($copy[$fromRes]); }
          $copy[$toRes] = ($copy[$toRes] ?? 0) + 1;
          $copy['sources'][] = $this->id;
          $newTrades[] = $copy;
        }
      }
    }
  }
  foreach ($newTrades as $t) {
    $args['costs']['trades'][] = $t;
  }
}

