methods.computeBonusScore:
public function computeBonusScore()
{
  $uid = $this->getExtraDatas('fieldUid');
  if ($uid === null) {
    return;
  }
  $player = $this->getPlayer();
  $fields = $player->board()->getEmptyFields();
  $field = null;
  foreach ($fields as $f) {
    $fUid = $f['uid'] ?? $f['x'] . '_' . $f['y'];
    if ($fUid === $uid) {
      $field = $f;
      break;
    }
  }
  if ($field === null) {
    return;
  }
  $location = $field['type'] == 'fieldCard' ? $field['id'] : 'board';
  $fences = Meeples::getResourcesOnCard($location, $player->getId(), FENCE);
  $count = 0;
  foreach ($fences as $fence) {
    if ($fence['x'] == $field['x'] && $fence['y'] == $field['y']) {
      $count++;
    }
  }
  if ($count > 0) {
    $this->addBonusScoringEntry($count);
  }
}

methods.getStableZones:
public function getStableZones($player = null)
{
  $player = $player ?? $this->getPlayer();
  $board = $player->board();
  $marks = $board->getPasturesMarks();
  $zones = [];

  foreach ($board->getStables() as $stable) {
    // Already converted stables can not be chosen again
    if (!empty($stable['state']) && $stable['state'] != 0) {
      continue;
    }
    // Only stables outside of any pasture can be turned into a wine cellar
    if (!is_null($marks[$stable['x']][$stable['y']])) {
      continue;
    }
    $zones[] = ['x' => $stable['x'], 'y' => $stable['y']];
  }

  return $zones;
}

