public function actConvertStable($zones)
{
  $player = $this->getPlayer();
  $validZones = $this->getStableZones($player);

  $zone = null;
  foreach ($zones as $picked) {
    foreach ($validZones as $valid) {
      if ($valid['x'] == $picked['x'] && $valid['y'] == $picked['y']) {
        $zone = $valid;
        break 2;
      }
    }
  }

  if (is_null($zone)) {
    throw new \BgaVisibleSystemException('C19_WineCellar : the selected zone is not a stable outside a pasture');
  }

  foreach ($player->board()->getStables() as $stable) {
    if ($stable['x'] == $zone['x'] && $stable['y'] == $zone['y']) {
      Stables::setValid($stable['id'], false);
      $this->setExtraDatas('stableId', $stable['id']);
      break;
    }
  }

  $player->board()->refresh();
  Notifications::updateDropZones($player);
  $player->forceReorganizeIfNeeded();
}

