  $this->setExtraDatas('doubleActionAvailable', false);
  $actionCardId = $event['actionCardId'] ?? null;
  if (empty($actionCardId)) {
    return null;
  }
  $actionCard = \AGR\Helpers\Utils::getActionCard($actionCardId);
  if ($actionCard && $actionCard->hasAccumulation()) {
    $accumulation = $actionCard->getAccumulation();
    $gain = [];
    foreach ($accumulation as $res => $amount) {
      $gain[$res] = $amount;
    }
    if (!empty($gain)) {
      return $this->gainNode($gain);
    }
  }
  return null;
}

  public function onPlayerPlaceFarmer($player, $event)
  {
    $actionCardId = $event['actionCardId'] ?? null;
    if (empty($actionCardId)) {
      return null;
    }

    $actionCard = ActionCards::get($actionCardId);
    if ($actionCard === null) {
      return null;
    }

    $actionType = $actionCard->getActionCardType();
    if (strpos($actionType, 'WishChildren') === false) {
      return null;
