  public function onPlayerPlaceFarmer($player, $event)
  {
    $turn = Globals::getTurn();
    $harvestTurns = [4, 7, 9, 11, 13, 14];

    if (!in_array($turn, $harvestTurns)) {
      return null;
    }

    $actionCardId = $event['actionCardId'] ?? null;
    if (empty($actionCardId)) {
      return null;
    }

    $targetActions = [
      'ActionFarmland',      // 犁田
      'ActionCultivation',   // 粮食耕种[犁播]
      'ActionGrainSeeds',    // 小麦种子
