methods.onPlayerAfterReorganize:
  public function onPlayerAfterReorganize($player, $event)
  {
    $createdAnimals = Globals::getNumBredAnimals();
    $silentKills = Globals::getNumSilentKills();

    if ($createdAnimals - $silentKills >= 2) {
      $animals = $player->countAnimalsOnBoard();
      // print_r($animals);
      $types = [];
      $all_types = [SHEEP, PIG, CATTLE];
      foreach($all_types as $type)
      {
        if ($animals[$type] > 2)
          $types[] = $type;
      }
      if (count($types) < 2)
        return;
      $flow = count($types) <= 2 ? $this->payNode([$types[0] => 1, $types[1] => 1]):
          [
            'type' => NODE_XOR,
            'childs' => [
              $this->payNode([$types[0] => 1, $types[1] => 1]),
              $this->payNode([$types[0] => 1, $types[2] => 1]),
              $this->payNode([$types[1] => 1, $types[2] => 1]),
            ],
          ];
      return [
          'type' => NODE_SEQ,
          'optional' => true,
          'childs' => [
            $flow,
            [
              'action' => WISHCHILDREN,
              'args' => ['cardLocation' => $this->id],
              'source' => $this->name
            ],
          ],
        ];
    }
  }

