methods.computeBonusScore:
public function computeBonusScore()
{
  $player = $this->getPlayer();
  $fields = $player->board()->getFieldTiles();
  // print_r($fields);
  $count = 0;
  foreach($fields as $field){
    $x = $field['x'];
    $y = $field['y'];
    $can_ = true;
    foreach($fields as $field2){
      if ($field2['id'] != $field['id']){
        $x2 = $field2['x'];
        $y2 = $field2['y'];
        if (abs($x2 - $x) + abs($y2 - $y) == 2){
          $can_ = false;
          break;
        }
      }
    }
    $count = $can_ ? $count + 1 : $count;
  }
  $bonus = 0;
  if ($count >= 3){
    $bonus++;
  }
  if ($count >= 4){
    $bonus++;
  }
  if ($count >= 5){
    $bonus++;
  }
  $this->addBonusScoringEntry($bonus);
}

