methods.onPlayerComputeCostsConstruct:
public function onPlayerComputeCostsConstruct($player, &$args)
{
  $all_trades = [];
  foreach ($args['costs']['trades'] as $trade) {
    if (isset($trade[REED])) {
      $reed = $trade[REED];
      for ($i = 1; $i <= $reed; $i++) {
        $trade[REED] -= $i;
        if ($trade[REED] <= 0) {
          unset($trade[REED]);
        }
        $trade[REED_BANK] = $i;
        $trade['sources'][] = $this->id;
        $all_trades[] = $trade;
        // $args['costs']['trades'][] = $trade;
      }
    }
  }
  foreach($all_trades as $trade)
    $args['costs']['trades'][] = $trade;
}

methods.onPlayerComputeCostsRenovation:
public function onPlayerComputeCostsRenovation($player, &$args)
{
  $all_trades = [];
  foreach ($args['costs']['fees'] as $fee) {
    $keys = array_diff(array_keys($fee), ['nb', 'max']);
    // print_r($keys);
    if (in_array(REED, $keys)) {
      $fee_reed = $fee[REED] ?? 0;
      for ($i = 1; $i <= $fee_reed; $i++)
      {
      $fee[REED_BANK] = $i;
      $fee[REED] -= $i;
      if ($fee[REED] == 0)
        unset($fee[REED]);
      $fee['sources'][] = $this->id;
      $all_trades[] = $fee;
      // Utils::addFees($args['costs'], $fee);
      }
    }
  }
  foreach($all_trades as $fee)
  {
    Utils::addFees($args['costs'], $fee);
  }
}

