methods.onPlayerPlaceFarmer:
public function onPlayerPlaceFarmer($player, $event)
{
  if ($this->isActionCardEvent($event, 'FarmRedevelopment') 
  || $this->isActionCardEvent($event, 'HouseRedevelopment')){
    $n_wood = count(Meeples::getResourcesOnCard($this->getId(), $this->getPlayer()->getId(), WOOD));
    $n_stone = count(Meeples::getResourcesOnCard($this->getId(), $this->getPlayer()->getId(), STONE));
    $flow = [];
    if ($n_wood + $n_stone <= 5){
      return [
          'action' => SPECIAL_EFFECT,
          'optional' => true,
          'args' => [
            'cardId' => $this->id,
            'method' => 'getResOnCard',
            'args' => [$n_wood, $n_stone]
          ]
          ];
    }
    else{
      for ($i = 0; $i <= 5; $i++){
        if ($i <= $n_wood && 5 - $i <= $n_stone)
          $flow[] = [
          'action' => SPECIAL_EFFECT,
          'optional' => true,
          'args' => [
            'cardId' => $this->id,
            'method' => 'getResOnCard',
            'args' => [$i, 5 - $i]
          ]
          ];
      }
      return [
        'type' => NODE_XOR,
        'optional' => true,
        'childs' => $flow
      ];
    }
    
}
  else{
  $iswood = $this->isActionCardEvent($event, 'Forest', null) 
  || $this->isActionCardEvent($event, 'Copse', null) 
  || $this->isActionCardEvent($event, 'Grove', null);
  $type = $iswood ? WOOD : STONE ;
  
  return [
    'action' => SPECIAL_EFFECT,
    'args' => [
                'cardId' => $this->id,
                'method' => 'accResoucce',
                'args' => [$type]
              ]
  ];
}
}

