methods.onPlayerCollect:
public function onPlayerCollect($player, $event)
{
  $meeples = $event['meeples'] ?? [];
  if (empty($meeples)) {
    return null;
  }
  $animalTypes = [SHEEP, PIG, CATTLE];
  $resourceMeeples = [];
  $animalMeeples = [];
  foreach ($meeples as $meeple) {
    if (in_array($meeple['type'], $animalTypes)) {
      $animalMeeples[] = $meeple;
    } else {
      $resourceMeeples[] = $meeple;
    }
  }
  $flow = [];
  if (!empty($resourceMeeples)) {
    $flow[] = ['action' => SPECIAL_EFFECT, 'args' => ['cardId' => $this->id, 'method' => 'moveResourcesToCard', 'args' => [array_column($resourceMeeples, 'id')]]];
  }
  if (!empty($animalMeeples)) {
    $flow[] = ['action' => SPECIAL_EFFECT, 'args' => ['cardId' => $this->id, 'method' => 'moveAnimalsToCard', 'args' => [array_column($animalMeeples, 'id')]]];
  }
  if (!empty($flow)) {
    return ['type' => NODE_SEQ, 'childs' => $flow];
  }
  return null;
}

