methods.checkFourOfAKind:
protected function checkFourOfAKind()
{
  $player = $this->getPlayer();
  $onCard = Meeples::getResourcesOnCard($this->id, $player->getId());
  $counts = [];
  foreach ($onCard as $meeple) {
    $type = $meeple['type'];
    if (!isset($counts[$type])) { $counts[$type] = []; }
    $counts[$type][] = $meeple;
  }
  $animalTypes = [SHEEP, PIG, CATTLE];
  foreach ($counts as $type => $meeples) {
    if (in_array($type, $animalTypes)) { continue; }
    if (count($meeples) >= 4) {
      $toMove = array_slice($meeples, 0, 4);
      $ids = array_column($toMove, 'id');
      Meeples::DB()->update(['meeple_location' => 'reserve'], $ids);
      foreach ($toMove as $m) {
        $m['location'] = 'reserve';
      }
      Notifications::placeMeeple($toMove);
    }
  }
}

methods.checkFourAnimals:
protected function checkFourAnimals()
{
  $player = $this->getPlayer();
  $onCard = Meeples::getResourcesOnCard($this->id, $player->getId());
  $counts = [];
  foreach ($onCard as $meeple) {
    $type = $meeple['type'];
    if (!isset($counts[$type])) { $counts[$type] = []; }
    $counts[$type][] = $meeple;
  }
  $animalTypes = [SHEEP, PIG, CATTLE];
  foreach ($counts as $type => $meeples) {
    if (!in_array($type, $animalTypes)) { continue; }
    if (count($meeples) >= 4) {
      $toMove = array_slice($meeples, 0, 4);
      $foodAmount = ($type == SHEEP) ? 1 : (($type == PIG) ? 2 : 3);
      $ids = array_column($toMove, 'id');
      Meeples::DB()->delete($ids);
      Notifications::silentKill($toMove);
      $created = $player->createResourceInReserve(FOOD, $foodAmount);
      Notifications::gainResources($player, $created, $this->id, $this->name);
    }
  }
}

