methods.actPlaceStone:
public function actPlaceStone($zones)
{
  $player = $this->getPlayer();
  $freeZones = $player->board()->getFreeZones();

  $zone = null;
  foreach ($zones as $picked) {
    foreach ($freeZones as $free) {
      if ($free['x'] == $picked['x'] && $free['y'] == $picked['y']) {
        $zone = $free;
        break 2;
      }
    }
  }

  if (is_null($zone)) {
    throw new \BgaVisibleSystemException('BI10_The52ndLatitude : the selected zone is not an empty farmyard space');
  }

  $this->setExtraDatas('stoneX', $zone['x']);
  $this->setExtraDatas('stoneY', $zone['y']);

  $created = Meeples::createResourceInLocation(STONE, 'board', $player->getId(), $zone['x'], $zone['y'], 1);
  Notifications::placeMeeple(Meeples::getMany($created));
}

methods.computeBonusScore:
public function computeBonusScore()
{
  $stoneX = $this->getExtraDatas('stoneX');
  $stoneY = $this->getExtraDatas('stoneY');
  if ($stoneX === null || $stoneY === null) {
    return;
  }
  $emptyFields = $this->getPlayer()->board()->getEmptyFields();
  $count = 0;
  foreach ($emptyFields as $field) {
    $fx = $field['x'];
    $fy = $field['y'];
    if (abs($fx - $stoneX) + abs($fy - $stoneY) == 1) {
      $count++;
    }
  }
  if ($count > 0) {
    $this->addBonusScoringEntry($count);
  }
}

