methods.onOpponentAfterExchange:
public function onOpponentAfterExchange($player, $event)
{
  $trades = $event['trades'];
  $exchanges = $event['exchanges'];
  $animalTypes = [SHEEP, PIG, CATTLE];
  $animalsToPlace = [];
  foreach ($trades as $tradeIndex) {
    if (is_array($tradeIndex) && ($tradeIndex['source'] ?? null) == 'discard') {
      continue;
    }
    $exchange = $exchanges[$tradeIndex] ?? null;
    if ($exchange) {
      $toFood = $exchange['to'][FOOD] ?? 0;
      if ($toFood <= 0) {
        continue;
      }
      $source = $exchange['source'] ?? null;
      if (!$this->isCookingSource($source)) {
        continue;
      }
      foreach ($animalTypes as $type) {
        $from = $exchange['from'][$type] ?? 0;
        if ($from > 0) {
          for ($i = 0; $i < $from; $i++) {
            $animalsToPlace[] = $type;
          }
        }
      }
    }
  }
  if (empty($animalsToPlace)) {
    return null;
  }
  return [
    'action' => SPECIAL_EFFECT,
    'args' => [
      'cardId' => $this->id,
      'method' => 'placeAnimalsOnCard',
      'args' => [$animalsToPlace],
    ],
  ];
}

