methods.isCookingSource:
private function isCookingSource($source)
{
  if ($source == null) {
    return false;
  }
  $cookingSources = [
    'Fireplace', 'Cooking Hearth', 'Oriental Fireplace', 'Earth Oven',
    'Clay Oven', 'Stone Oven', 'Baker\'s Oven', 'Wood-fired Oven',
    'Cast-iron Oven', 'Beehive Oven', 'Errant Oven',
  ];
  foreach ($cookingSources as $cs) {
    if (mb_stripos($source, $cs) !== false) {
      return true;
    }
  }
  return false;
}

