methods.onBuy:
public function onBuy($player){
  // $n_stone = Meeples::getReserveResource($player->getId(), STONE);
  // $n_room_space = 0;
  $rooms = Meeples::getRooms($player->getId())->toArray();
  
  $num_ = 0;
  foreach ($rooms as $room){
    $x = $room['x'];
    $y = $room['y'];
    
    foreach($rooms as $room2){
      if ($room2['id'] != $room['id']){
        $x2 = $room2['x'];
        $y2 = $room2['y'];
        if (abs($x2 - $x) + abs($y2 - $y) == 2){
          $num_ += 1;
        }
      }
    }
  }
  $n_room_space = $num_ / 2;
  $flow = [];
  for ($i = 1; $i <= $n_room_space; $i++){
    $flow[] = 
      [
          'type' => NODE_SEQ,
          'optional' => false,
          'childs' => [
          $this->payNode([STONE => $i]),
          [
          'action' => SPECIAL_EFFECT,
          'args' => [
                'cardId' => $this->id,
                'method' => 'putres',
                'args' => [$i]
              ]
          ]
          ]
      ];
  }
  return [
    'type' => NODE_XOR,
    'optional' => true,
    'childs' => $flow
  ];
}

