methods.gainFoodFromBread:
protected function gainFoodFromBread($event)
{
  $trades = $event['trades'];
  $exchanges = $event['exchanges'];
  $grainCount = 0;
  foreach ($trades as $tradeIndex) {
    if (is_array($tradeIndex) && ($tradeIndex['source'] ?? null) == 'discard') {
      continue;
    }
    $exchange = $exchanges[$tradeIndex] ?? null;
    if ($exchange) {
      $grain = $exchange['from'][GRAIN] ?? null;
      $food = $exchange['to'][FOOD] ?? null;
      if (!is_null($grain) && !is_null($food)) {
        $grainCount += $grain;
      }
    }
  }
  if ($grainCount > 0) {
    return $this->gainNode([FOOD => $grainCount]);
  }
  return null;
}

methods.onPlayerAfterExchange:
public function onPlayerAfterExchange($player, $event)
{
  $trades = $event['trades'];
  $exchanges = $event['exchanges'];
  $pigCount = 0;
  foreach ($trades as $tradeIndex) {
    if (is_array($tradeIndex) && ($tradeIndex['source'] ?? null) == 'discard') { continue; }
    $exchange = $exchanges[$tradeIndex] ?? null;
    if ($exchange) {
      $fromPig = $exchange['from'][PIG] ?? 0;
      $toFood = $exchange['to'][FOOD] ?? 0;
      if ($fromPig > 0 && $toFood > 0) {
        $pigCount += $fromPig;
      }
    }
  }
  if ($pigCount > 0) {
    return ['action' => SPECIAL_EFFECT, 'args' => ['cardId' => $this->id, 'method' => 'placePigsOnCard', 'args' => [$pigCount]]];
  }
  return null;
}

