  public function computeBonusScore()
  {
    $playerthis = $this->getPlayer();
    $maxsheep = 0;
    $maxpig=0;
    $maxcattle=0;
    foreach (Players::getAll() as $player) {
      $sheeps = $player->countAnimalsOnBoard()[SHEEP];
      $pigs = $player->countAnimalsOnBoard()[PIG];
      $cattles=$player->countAnimalsOnBoard()[CATTLE];
      if ($sheeps  > $maxsheep) {
        $maxsheep = $sheeps ;
      }
      if ($pigs  > $maxpig) {
        $maxpig = $pigs ;
      }
      if ($cattles  > $maxcattle) {
        $maxcattle = $cattles ;
      }
    }

    if ($playerthis->countAnimalsOnBoard()[SHEEP] == $maxsheep)
    {
      if ($playerthis->countAnimalsOnBoard()[PIG] == $maxpig)
      {
        if ($playerthis->countAnimalsOnBoard()[CATTLE] == $maxcattle)
        {
          $this->addBonusScoringEntry(3);
        }
      }
    }
    
    $this->addBonusScoringEntry(0);
  }

