methods.computeBonusScore:
public function computeBonusScore()
{
  $player = $this->getPlayer();
  $bonus = 0;
  
  $n = count($player->board()->getFieldTiles());
  if($n >=5 ) $bonus ++;
  $n = count($player->board()->getPastures());
  if($n >=4 ) $bonus ++;
  $n = $player->countReserveResource(GRAIN) + $player->board()->getGrowingCrops(GRAIN)->count();
  if($n >=8 ) $bonus ++;
  $n = $player->countReserveResource(VEGETABLE) + $player->board()->getGrowingCrops(VEGETABLE)->count();
  if($n >=4 ) $bonus ++;
  $n = $player->getExchangeResources()[SHEEP];
  if($n >=8 ) $bonus ++;
  $n = $player->getExchangeResources()[PIG];
  if($n >=7 ) $bonus ++;
  $n = $player->getExchangeResources()[CATTLE];
  if($n >=6 ) $bonus ++;
  $pastures = $player->board()->getPastures();
  $n = \array_reduce(
    $pastures,
    function ($acc, $pasture) {
      return $acc + count($pasture['stables']);
    },
    0
  );
  if($n >=4 ) $bonus ++;
  $this->addBonusScoringEntry($bonus);
}

