methods.onPlayerAfterStables:
  public function onPlayerAfterStables($player, $event)
  {
    $inReserve = $player->countStablesInReserve();
    $nAfter = count($player->board()->getStables());
    $n = count($event['stables']);
    $nBefore = $nAfter - $n;
    $gains = [];
    for ($i = $nBefore + 1; $i <= $nAfter; $i++) {
      if ($i == 2) {
        $gains[CATTLE] = 1;
      }
      if ($i == 3) {
        $gains[PIG] = 1;
      }
      if ($i == 4) {
        $gains[SHEEP] = 1;
      }
    }

    if ($gains != []) {
      return $this->gainNode($gains);
    }
  }

