  public function onPlayerAfterRenovation($player, $event)
  {
    $clay = -1;
    $stone = -1;
    foreach (Players::getAll() as $playert) {
      if ($playert->getRoomType() == 'roomClay')
      {
        $clay+=1;
      }
      if ($playert->getRoomType() == 'roomStone')
      {
        $clay+=1;
        $stone+=1;
      }
    }
    
    if ($player->getRoomType() == 'roomClay' && $clay < 3)
    {
      return $this->gainNode([STONE => 3-$clay]);
    }

    if ($player->getRoomType() == 'roomStone' && $clay < 3)
    {
      return $this->gainNode([STONE => 3-$stone]);
    }

    return null;
  }

