  $n_food = count(Meeples::getResourcesOnCard('TravelingPlayers', null, FOOD));
  $flow[] = $this->gainNode([FOOD => $n_food]);
  $cards_ = ['E167_Conjurer', 'E169_Storyteller', 'E212_Dancer', 'I249_Puppeteer', 'I257_StreetMusician', 'K269_Acrobat', 'K311_Magician', 'K342_AnimalTrainer'];
  foreach (Players::getAll() as $player2) {
    if ($player2->getId() == $player->getId()) continue;
    $n_has = 0;
    foreach($cards_ as $card)
    {
      if ($player2 -> hasPlayedCard($card))
        $n_has += 1;
      if ($n_has > 0)
        $flow[] = $this->payNode([FOOD => $n_has], null, 1, $player2->getId());
    }
  }
  return 
  [
    'type' => NODE_SEQ,
    'optional' => true,
    'childs' => $flow
    ];
}

