methods.removeClay:
protected function removeClay(&$args, $nb)
{
  foreach ($args['costs']['trades'] as &$trade) {
    if (isset($trade[CLAY])) {
      $trade[CLAY] -= $nb;
      if ($trade[CLAY] <= 0) {
        unset($trade[CLAY]);
      }
      $trade['sources'][] = $this->id;
    }
  }
}

