methods.onBuy:
 public function onBuy($player)
{
  $turn = Globals::getTurn();
  $turns = [];
  $count = 0;
  if (($turn + 6) <= 14)
  {
    $turns[] = $turn + 6;
    $count += 4;
  }
  if (($turn + 10) <= 14)
  {
    $turns[] = $turn + 10;      
    $count += 4;
  }
  if (count($turns) > 0)
    $this->setExtraDatas('turns', $turns);
  else
