methods.onPlayerAfterGain:
  public function onPlayerAfterGain($player, $event)
  {
    $actionCardId = $event['actionCardId'] ?? null;
    $cards = array_column(ActionCards::getVisible($player) -> toArray(), 'id');
    if (!in_array($actionCardId, $cards))
      return;

    $all_type = [WOOD, CLAY, REED, STONE, GRAIN, VEGETABLE];
    $meeples = $event['meeples'];
    $found_type = [];
    foreach ($meeples as $meeple) {
      if (!in_array($meeple['type'], $found_type) && in_array($meeple['type'], $all_type)) {
        $found_type[] = $meeple['type'];
      }
    }
    $flow = [];
    foreach($found_type as $type){
      if ($type != VEGETABLE)
        $flow[] = $this->payGainNode([FOOD => 1], [$type => 1], null, false);
      else
        $flow[] = $this->payGainNode([FOOD => 2], [$type => 1], null, false);
    }
    if (count($flow) > 0)
      return ['type' => NODE_OR, 'optional' => true, 'childs' => $flow];
  }

