  public function computeBonusScore()
  {
    $wood = Meeples::getResourcesOnCard($this->id, null, WOOD)->count();
    $bonus = $wood;
    
    if ($wood == 0) {return;}
    if ($wood >= 1) {$bonus--;}
    if ($wood >= 4) {$bonus--;}
    if ($wood >= 7) {$bonus--;}
    if ($wood >= 10) {$bonus--;}

    $this->addBonusScoringEntry($bonus);    
  }

  public function computeBonusScore()
  {
    $player = $this->getPlayer();
    $bonus = 0;

    $zones = $player->board()->getAnimalsDropZonesWithAnimals();
    foreach ($zones as $zone) {
      if ($zone['type'] != 'pasture') {
        continue;
      }
      if ($zone['animals'] > 0 && $zone['capacity'] - $zone['animals'] >= 3) {
        $bonus++;
      }
    }

    if ($bonus != 0) {
      $this->addBonusScoringEntry($bonus);
    }
  }

