methods.onPlayerAfterExchange:
  public function onPlayerAfterExchange($player, $event)
  {
    $trades = $event['trades'];
    $exchanges = $event['exchanges'];
    $pigCount = 0;
    $cattleCount = 0;

    foreach ($trades as $tradeIndex) {
      if (is_array($tradeIndex) && $tradeIndex['source'] == 'discard') {
        continue;
      }
      $exchange = $exchanges[$tradeIndex] ?? null;
      if ($exchange) {
        $ispig = $exchange['from'][PIG] ?? 0;
        $iscattle = $exchange['from'][CATTLE] ?? 0;
        $isfood = $exchange['to'][FOOD] ?? 0;
        if ($isfood > 0) {
          $pigCount += $ispig;
          $cattleCount += $iscattle;
        }
      }
    }

    if ($pigCount == 0 && $cattleCount == 0) {
      return null;
    }

    return [
      'type' => NODE_SEQ,
      'optional' => true,
      'childs' => [
        [
          'action' => SPECIAL_EFFECT,
          'args' => [
            'cardId' => $this->id,
            'method' => 'storeAnimals',
            'args' => [$pigCount, $cattleCount],
          ],
        ],
      ],
    ];
  }

methods.storeAnimals:
  public function storeAnimals($pigCount, $cattleCount)
  {
    $player = Players::getActive();
    $stored = [];

    // Trophies are not spendable animals: store them with player_id 0 so payments/scoring ignore them
    if ($pigCount > 0) {
      $ids = Meeples::createResourceInLocation(PIG, $this->id, 0, 0, 0, $pigCount);
      foreach ($ids as $id) {
        $stored[] = Meeples::get($id);
      }
    }

    if ($cattleCount > 0) {
      $ids = Meeples::createResourceInLocation(CATTLE, $this->id, 0, 0, 0, $cattleCount);
      foreach ($ids as $id) {
        $stored[] = Meeples::get($id);
      }
    }

    if (!empty($stored)) {
      Notifications::gainResources($player, $stored, $this->id, $this->name);
    }
  }

methods.computeBonusScore:
  public function computeBonusScore()
  {
    $pigs = Meeples::getResourcesOnCard($this->id, null, PIG)->count();
    $cattle = Meeples::getResourcesOnCard($this->id, null, CATTLE)->count();

    $pigScore = 0;
    if ($pigs >= 6) {
      $pigScore = 3;
    } elseif ($pigs >= 4) {
      $pigScore = 2;
    } elseif ($pigs >= 2) {
      $pigScore = 1;
    }

    $cattleScore = 0;
    if ($cattle >= 4) {
      $cattleScore = 3;
    } elseif ($cattle >= 3) {
      $cattleScore = 2;
    } elseif ($cattle >= 2) {
      $cattleScore = 1;
    }

    $bonus = $pigScore + $cattleScore;
    $this->addBonusScoringEntry($bonus);
  }

