        $tofish+=1;
      }
    }
    if ($wood - $ave == 2)
    {
      if ($rand != 10)
      {
        $toclay+=1;
      }
      if ($rand != 11)
      {
        $toreed+=1;
      }
      if ($rand != 12)
      {
        $tofish+=1;
      }
    }


    // foreach (Meeples::getResourcesOnCard('ActionForest') as $meeple) {
