methods.AllocationWood:
public function AllocationWood($toclay, $toreed, $tofish)
{
  $meeples = array_merge(Meeples::getResourcesOnCard('ActionForest', null, WOOD) -> toArray(), 
Meeples::getResourcesOnCard('ActionForestSolo', null, WOOD) -> toArray());
  // print_r($meeples);
  $meps = [];
  foreach($meeples as $res){
    if ($toclay > 0)
    {
    Meeples::moveToCoords($res['id'], 'ActionClayPit');
    $res['location'] = 'ActionClayPit';
    $meps[] = $res;
    $toclay -= 1;
    }
    else if ($toreed > 0)
    {
    Meeples::moveToCoords($res['id'], 'ActionReedBank');
    $res['location'] = 'ActionReedBank';
    $meps[] = $res;
    $toreed -= 1;
    }
    else if ($tofish > 0)
    {
    Meeples::moveToCoords($res['id'], 'ActionFishing');
    $res['location'] = 'ActionFishing';
    $meps[] = $res;
    $tofish -= 1;
    }
    // print_r($toclay);
  }
  Notifications::placeMeeple($meps);
  // Meeples::moveToCoords($res['id'], $this->id);
  // $res['location'] = $this->id;
  // Notifications::placeMeeple([$res]);
}

