methods.onPlayerAfterSow:
public function onPlayerAfterSow($player, $event)
{
  $fieldCount = count($player->board()->getFields());
  if ($fieldCount > 2) {
    return null;
  }
  $sows = $event['sows'] ?? [];
  if (empty($sows)) {
    return null;
  }
  $notifSows = [];
  foreach ($sows as $sow) {
    $field = $sow['field'];
    $type = $sow['type'];
    if (!in_array($type, [GRAIN, VEGETABLE])) {
      continue;
    }
    $location = ($field['type'] ?? '') == 'fieldCard' ? $field['id'] : 'board';
    $ids = Meeples::createResourceInLocation(
      $type,
      $location,
      $field['pId'],
      $field['x'],
      $field['y'],
      1
    );
    $notifSows[] = ['field' => $field, 'type' => $type, 'crops' => Meeples::getMany($ids)->toArray()];
  }
  if (!empty($notifSows)) {
    Notifications::sow($player, $notifSows, true);
  }
  return null;
}

