public function onPlayerStartOfWork($player, $event)
{
  for($i=1;$i>0;$i++)
  {
    $rand1 = rand(1,$this->n);
    $rand2 = rand(1,$this->n);
    if ($rand1 != $rand2)
    {
      break;
    }
  }
  if ($rand1<=$this->sheep && $rand2<=$this->sheep)
  {
    $this->sheep-=1;
    $this->pig-=1;
    $this->cattle-=1;
    $this->n-=1;
    return $this->gainNode([SHEEP => 1]);		
  }
  if ($rand1<=$this->pig && $rand2<=$this->pig && $rand1>$this->sheep && $rand2>$this->sheep)
  {
    $this->pig-=1;
    $this->cattle-=1;
    $this->n-=1;
    return $this->gainNode([PIG => 1]);		
  }
  if ($rand1<=$this->cattle && $rand2<=$this->cattle && $rand1>$this->pig && $rand2>$this->pig)
  {
    $this->cattle-=1;
    $this->n-=1;
    return $this->gainNode([CATTLE => 1]);		
  }
  return [
    'type' => NODE_SEQ,
    'childs' => [
      $this->gainNode([FOOD=>1]),
      $this->payNode([FOOD=>1])
    ]
  ];
}

