methods.computeBonusScore:
  public function computeBonusScore()
  {
    $player = $this->getPlayer();
    $board = $player->board();
    $rooms = $board->getRooms();
    $fields = $board->getFields();
    $pastures = $board->getPastures();

    $count_rooms = [1=>0, 3=>0, 5=>0, 7=>0, 9=> 0];
    foreach ($rooms as $room)
      $count_rooms[$room['x']] += 1;
    $count_fields = [1=>0, 3=>0, 5=>0, 7=>0, 9=> 0];
    foreach ($fields as $field)
      $count_fields[$field['x']] += 1;
    
    $bonus = 0;
    foreach ($count_rooms as $key => $value) {
      if ($value == 3)
        $bonus += 1;
    }
    foreach ($count_fields as $key => $value) {
      if ($value == 3)
        $bonus += 1;
    }
    foreach ($pastures as $pasture)
    {
      $count_pastures = [1=>0, 3=>0, 5=>0, 7=>0, 9=> 0];
      foreach ($pasture['nodes'] as $node)
        $count_pastures[$node['x']] += 1;
      foreach ($count_pastures as $key => $value) {
        if ($value == 3)
          $bonus += 1;
      }
    }
    
    // print_r($rooms);
    // print_r($fields);
    // print_r($pastures);
    
    // $bonusMap = [0, 0, 0, 0, 0, 1, 3, 5, 7, 9];
    // $bonus = $bonusMap[$player->countAllImprovements()] ?? 9;
    $this->addBonusScoringEntry($bonus);
  }

methods.calcTradeReplace:
  function calcTradeReplace($trade, $max = 1)
  {
    $replacement = [];
    $resList = [WOOD, CLAY, STONE, REED];

    // 只保留该支付方案中实际存在的建筑资源
    $types = [];
    foreach ($resList as $r) {
      if (isset($trade[$r]) && $trade[$r] > 0) {
        $types[] = $r;
      }
    }

    if (empty($types)) {
      return $replacement;
    }

    $this->genReplacements($types, $trade, 0, [], 0, $max, $replacement);
    return $replacement;
  }

methods.genReplacements:
private function genReplacements($types, $trade, $idx, $current, $total, $max, &$results)
{
  if ($total > $max) {
    return;
  }
  if ($idx == count($types)) {
    if ($total > 0) {
      $copy = $trade;
      foreach ($current as $r => $count) {
        if ($count > 0) {
          $copy[$r] -= $count;
          if ($copy[$r] <= 0) {
            unset($copy[$r]);
          }
        }
      }
      $copy[FOOD] = ($copy[FOOD] ?? 0) + $total;
      $copy['sources'][] = $this->id;
      $results[] = $copy;
    }
    return;
  }
  $r = $types[$idx];
  $maxCount = min($trade[$r], $max - $total);
  for ($c = 0; $c <= $maxCount; $c++) {
    $current[$r] = $c;
    $this->genReplacements($types, $trade, $idx + 1, $current, $total + $c, $max, $results);
  }
}

