methods.reduceCosts:
private function reduceCosts(&$args)
{
    $resourcesOnCard = Meeples::getResourcesOnCard($this->id, null);

    if (!$resourcesOnCard->empty()) {
        // 统计每种资源在卡牌上的数量
        $resourceCounts = [];
        foreach ($resourcesOnCard as $meeple) {
            $resourceType = $meeple['type'];
            if (!isset($resourceCounts[$resourceType])) {
                $resourceCounts[$resourceType] = 0;
            }
            $resourceCounts[$resourceType]++;
        }
    }
    else
    {
        return;
    }
    $all_trades = [];
    $trade_key = [WOOD => WOOD_EXPERT, CLAY => CLAY_EXPERT, REED => REED_EXPERT, STONE => STONE_EXPERT];
    foreach ($args['costs']['fees'] as $fee) {
        $keys = array_diff(array_keys($fee), ['nb', 'max']);
        foreach($resourceCounts as $resourceType => $count)
        {
        if (in_array($resourceType, $keys)) {
            $fee_resource = min($fee[$resourceType], $count) ?? 0;
            for ($i = 1; $i <= $fee_resource; $i++)
            {
                $fee[$trade_key[$resourceType]] = $i;
                $fee[$resourceType] -= $i;
                if ($fee[$trade_key[$resourceType]] == 0)
                unset($fee[$trade_key[$resourceType]]);
                $fee['sources'][] = $this->id;
                $all_trades[] = $fee;
            // Utils::addFees($args['costs'], $fee);
            }
        }
    }
    }
    foreach($all_trades as $fee)
    {
        Utils::addFees($args['costs'], $fee);
    }
}

