methods.addResourceToCard:
public function addResourceToCard($resource, $paidResources, $builderId)
{
    if (!in_array($resource, [WOOD, CLAY, REED, STONE], true) ||
        !in_array($resource, $paidResources, true)) {
        throw new \BgaVisibleSystemException('Expert Builder requires an actually paid building resource');
    }
    // PAY has already removed this piece. Re-create it on the card, without
    // charging the builder a second time or adding it to the owner's reserve.
    $created = Meeples::createResourceOnCard($resource, $this->id);
    Notifications::accumulate(Meeples::getMany($created), true);
    Notifications::message(clienttranslate('${player_name}将实际支付的1个${resource_icon}放在${card_name}上'), [
        'player' => Players::get($builderId),
        'card' => $this,
        'resource_icon' => '<' . strtoupper($resource) . '>',
    ]);
}

