    $max = 666;
    $bonusPlayers = [];
    foreach (Players::getAll() as $player) {
      $fencedStables = $player->getPlayedCards()->count();
      
      if ($fencedStables < $max) {
        $max = $fencedStables;
        $bonusPlayers = [];
