public function onPlayerAtAnytime($player, $event)
{
  $n = $this->getExtraDatas('E53Converted') ?? 0;
  $n = $this->getExtraDatas('ConvertedPig') ?? 0;
  $ns = $this->getExtraDatas('ConvertedSheep') ?? 0;
  $nc = $this->getExtraDatas('ConvertedCattle') ?? 0;
  if ($n > 0 || $ns >0 || $nc > 0) {
    for ($i = 0; $i <= $n; $i++) {
      for ($j = 0; $j <= $ns; $j++)
      {
        for ($k = 0; $k <= $nc; $k++)
        {
          $childpay = $this->payGainNode([PIG => $i, SHEEP => $j, CATTLE => $k], [FOOD => $i*3+$j*2+$k*4], null, false);
       if($player->hasPlayedCard('E85_MasterTanner')){
         $childall = [
           'type' => NODE_SEQ,
           'optional' => false,
           'childs' => [
             $childpay,
             [
               'action' => SPECIAL_EFFECT,
               'args' => [
                 'cardId' => 'E85_MasterTanner',
                 'method' => 'increaseCattleOrPigCooked',
                 'args' => [$i],
               ],
             ],
           ],
         ];
         $childs[] = $childall;
       }
       else{
        $childs[] = $childpay;
       } 
    }
    $child = [
      'type' => NODE_XOR,
      'optional' => false,
      'childs' => $childs,
    ];
    return [
      'type' => NODE_SEQ,
      'childs' => [
        $this->unflagCardNode('E53Converted'),
        $child,
      ],
    ];
        }
      }
  }
