    return;
  }
  $meeples = $event['meeples'];
  $n = 0;
  $ids = $this->getExtraDatas('ids');
  if($ids==null){
    $ids = [];
  }
  foreach ($meeples as $meeple) {
    if ($meeple['type'] == PIG && !in_array($meeple['id'],$ids)) {
      $n++;
       $ids[] = $meeple['id'];
    }
  }
  if ($n > 0) {
    for ($i = 1; $i <= $n; $i++) {
       $childpay = $this->payGainNode([PIG => $i], [FOOD => $i*4], null, false);
       if($player->hasPlayedCard('E85_MasterTanner')){
         $childall = [
           'type' => NODE_SEQ,
           'optional' => false,
           'childs' => [
             $childpay,
             [
               'action' => SPECIAL_EFFECT,
               'args' => [
                 'cardId' => 'E85_MasterTanner',
                 'method' => 'increaseCattleOrPigCooked',
                 'args' => [$i],
               ],
             ],
           ],
         ];
         $childs[] = $childall;
       }
       else{
        $childs[] = $childpay;
       } 
    }
    $child = [
      'type' => NODE_XOR,
      'optional' => false,
      'childs' => $childs,
    ];
    $setIds = [
        'action' => SPECIAL_EFFECT,
        'args' => [
          'cardId' => $this->id,
          'method' => 'setIds',
          'args' => [$ids],
        ]
      ];
     return [
      'type' => NODE_SEQ,
      'optional' => true,
      'childs' => [$child,
       $setIds,],
    ];
  }
}

