public function onPlayerAfterCollect($player, $event)
{
  $gain = $event['gain'] ?? [];
  $buildingTypes = [WOOD, CLAY, REED, STONE];
  $gainedBuilding = [];
  foreach ($buildingTypes as $type) {
    if (isset($gain[$type]) && $gain[$type] > 0) {
      $gainedBuilding[$type] = $gain[$type];
    }
  }
  if (empty($gainedBuilding)) return null;

  $childs = [];
  foreach ($buildingTypes as $type) {
    if (!isset($gainedBuilding[$type])) continue;
    $withBonus = $gainedBuilding;
    $withBonus[$type] = ($withBonus[$type] ?? 0) + 1;
    $total = array_sum($withBonus);
    $turn = Globals::getTurn();
    $turns = [];
    for ($i = 1; $i <= $total; $i++) {
      $turns[] = $turn + $i;
    }
    $resList = [];
    foreach ($withBonus as $rtype => $amt) {
      for ($i = 0; $i < $amt; $i++) {
        $resList[] = $rtype;
      }
    }
    $resources = [];
    foreach ($resList as $idx => $rtype) {
      $resources[$turns[$idx]] = [$rtype => 1];
    }
    $childs[] = [
      'type' => NODE_SEQ,
      'childs' => [
        $this->payNode($gainedBuilding),
        $this->futureMeeplesNode($resources, array_keys($resources), $this->id),
      ],
    ];
  }
  if (empty($childs)) return null;
  return [
    'type' => NODE_XOR,
    'optional' => true,
    'childs' => $childs,
  ];
}

