methods.PlaceGrain:
public function PlaceGrain(){
  $player = $this->getPlayer();
  $emptyFields = $player->board()->getEmptyFields();
  $sows = [];
  foreach ($emptyFields as $field) {
      $location = $field['type'] == 'fieldCard' ? $field['location'] : 'board';
      if (isset($field['constraints'])) {
        if (GRAIN !== $field['constraints']) {
          continue;
        }
      }
      $ids = Meeples::createResourceInLocation(
        GRAIN,
        $location,
        $field['pId'],
        $field['x'],
        $field['y'],
        1
      );
      $sows[] = [
        'field' => $field,
        'type' => GRAIN,
        'crops' => Meeples::getMany($ids)->toArray(),
      ];
  }
  if (empty($sows)) {
    return;
  }
  Notifications::sow($player, $sows, true);
}

