methods.ChangeRes:
public function ChangeRes(){
  $res = $this->getResourcesOrderedByState();
  if (count($res) == 0) return;
  $top = $res[count($res) - 1];
  $type = $top['type'];
  $minState = $res[0]['state'];
  Meeples::DB()->delete($top['id']);
  Notifications::silentKill([$top]);
  $created = Meeples::createResourceInLocation($type, $this->id, $this->getPlayer()->getId(), null, null, 1, $minState - 1);
  Notifications::accumulate(Meeples::getMany($created), true);
}

methods.onPlayerAfterExchange:
public function onPlayerAfterExchange($player, $event) {
  $trades = $event['trades'];
  $exchanges = $event['exchanges'];
  $res = $this->getResourcesOrderedByState();
  if (count($res) == 0) return;
  $topType = $res[count($res) - 1]['type'];
  $bottomType = $res[0]['type'];
  $hasTop = false;
  $hasBottom = false;
  foreach ($trades as $tradeIndex) {
    if (is_array($tradeIndex) && $tradeIndex['source'] == 'discard') {
      continue;
    }
    $exchange = $exchanges[$tradeIndex] ?? null;
    if ($exchange) {
      foreach($exchange['to'] as $resource => $amount) {
        if ($resource == $topType) $hasTop = true;
        if ($resource == $bottomType) $hasBottom = true;
      }
    }
  }
  $flow = [];
  if ($hasTop)
    $flow[] = [
      'type' => NODE_SEQ,
      'childs' => [
        $this->flagCardNode(),
        $this->gainNode([$topType => 1]),
        $this->unflagCardNode()
      ]
    ];
  if($hasBottom)
    $flow[] = $this->payNode([$bottomType => 1]);
  if (count($flow) > 0)
    return [
      'type' => NODE_SEQ,
      'childs' => $flow
    ];
}

