methods.onPlayerComputeCostsConstruct:
public function onPlayerComputeCostsConstruct($player, &$args)
{
  $n_animals = count($this->getPlayer()->getAnimalsOnBoard());
  $n = 0;
  if ($n_animals >= 1) $n++;
  if ($n_animals >= 2) $n++;
  if ($n_animals >= 4) $n++;
  if ($n_animals >= 7) $n++;
  if ($n <= 0) return;
  $free = [];
  $trades = [];
  // $res_all = [WOOD, REED];
  for ($i=0;$i<=$n;$i++) $free[] = [WOOD => $i, REED => $n - $i];
  if ($args['type'] == 'roomWood') {
    foreach ($args['costs']['trades'] as $trade) {
      // print_r($trade);
      if (($trade[WOOD] ?? 0) + ($trade[REED] ?? 0) <= $n)
      {
        $trade_ = $trade;
        unset($trade_[WOOD]);
        unset($trade_[REED]);
        $trades[] = $trade_;
        continue;
      }
      foreach ($free as $f){
        if (isset($trade[REED]))
        {
          foreach ($free as $f){
            if (($trade[WOOD] ?? 0) < $f[WOOD] || ($trade[REED] ?? 0) < $f[REED])
              continue;
            $trade_ = $trade;
            $trade_[WOOD] -= $f[WOOD];
            $trade_[REED] -= $f[REED];
            if ($trade_[WOOD] <= 0) unset($trade_[WOOD]);
            if ($trade_[REED] <= 0) unset($trade_[REED]);
            $trade_['sources'][] = $this->id;
            $trades[] = $trade_;
          }
        }
        else{
          $trade_ = $trade;
          $trade_[WOOD] -= $n;
          if ($trade_[WOOD] <= 0) unset($trade_[WOOD]);
          $trade_['sources'][] = $this->id;
          $trades[] = $trade_;
        }
      }
  }
  }
  // print_r($trades);
  foreach($trades as $trade) Utils::addCost($args['costs'], $trade);
}

