methods.onPlayerEndWorkPhase:
public function onPlayerEndWorkPhase($player, $event)
{
  $turn = Globals::getTurn();
  
  if ($turn < 4) {
    return null;
  }
  
  $familyCount = $player->countFarmers();
  $actionSpacesUsed = $player->countPlacedFarmers();
  
  if ($familyCount > 2 || $actionSpacesUsed > 2) {
    return null;
  }
  
  $options = [];
  
  $options[] = $this->gainNode([FOOD => 1]);
  
  if ($turn >= 8) {
    $options[] = $this->gainNode([SHEEP => 1]);
    $options[] = $this->gainNode([PIG => 1]);
    $options[] = $this->gainNode([CATTLE => 1]);
  }
  
  if ($turn >= 12) {
    $options[] = [
      'action' => PLOW,
      'args' => [
        'source' => $this->name,
        'cardId' => $this->id,
      ],
      'pId' => $this->pId,
    ];
  }
  
  if (count($options) == 1) {
    return $options[0];
  }
  
  return [
    'type' => NODE_XOR,
    'optional' => true,
    'childs' => $options,
  ];
}

