public function isvalidim($event)
{
  if ($event['types'][0] == MINOR)
  {
  $card = PlayerCards::get($event['cardId']);
  if ($card->getType() == MAJOR)
    return false;
  $costs = $card->getBaseCosts();
  $flow = [];
  $resources = [WOOD, CLAY, REED, STONE];
  foreach ($resources as $res){
    foreach ($costs as $cost) {
      if (isset($cost[$res]) && $cost[$res] >= 1) 
        if (count(Meeples::getResourcesOnCard($this->getId(), null, $res)) > 0)
          $flow[] = [
          'action' => SPECIAL_EFFECT,
          'args' => [
                      'cardId' => $this->id,
