methods.checkAnimalMatch:
private function checkAnimalMatch($player, $meeples)
{
  $animals = [SHEEP, PIG, CATTLE];
  $onCard = Meeples::getResourcesOnCard($this->id, null);
  if ($onCard->count() == 0) return null;
  $arr = $onCard->toArray();
  $topAnimal = null;
  for ($i = count($arr) - 1; $i >= 0; $i--) {
    if (in_array($arr[$i]['type'], $animals)) {
      $topAnimal = $arr[$i]['type'];
      break;
    }
  }
  if ($topAnimal == null) return null;
  $found = false;
  foreach ($meeples as $meeple) {
    if ($meeple['type'] == $topAnimal) {
      $found = true;
      break;
    }
  }
  if (!$found) return null;
  $toGain = [$topAnimal => 1];
  return [
    'type' => NODE_SEQ,
    'optional' => true,
    'childs' => [
      $this->gainNode($toGain),
    ],
  ];
}

