methods.onPlayerAfterExchange:
  public function onPlayerAfterExchange($player, $event)
  {
    $trigger = $event['trigger'] ?? null;
    if ($trigger !== HARVEST) {
      return null;
    }

    $exchanges = $event['exchanges'];
    $trades = $event['trades'];
    $cardCount = 0;

    foreach ($trades as $tradeIndex) {
      if (is_array($tradeIndex) && $tradeIndex['source'] == 'discard') {
        continue;
      }

      $exchange = $exchanges[$tradeIndex] ?? null;
      $isfood = $exchange['to'][FOOD] ?? null;
      if (!is_null($isfood) && 
      (!is_null($exchange['from'][WOOD] ?? null) || !is_null($exchange['from'][CLAY] ?? null) || !is_null($exchange['from'][STONE] ?? null) || !is_null($exchange['from'][REED] ?? null)))
      {
        if ($exchange && isset($exchange['flag']) && $exchange['flag'] != null) {
          $card = PlayerCards::get($exchange['flag']);
          if ($card && ($card instanceof \AGR\Models\Occupation || $card instanceof \AGR\Models\MinorImprovement || $card instanceof \AGR\Models\MajorImprovement)) {
            $cardCount++;
          }
        }
      }
    }

    if ($cardCount > 0) {
      return $this->gainNode([FOOD => $cardCount]);
    }

    return null;
  }

methods.onPlayerComputeCostsImprovement:
  public function onPlayerComputeCostsImprovement($player, &$args)
  {
    $playerCount = Players::count();
    // $playerCount = $player->getPlayerCount();
    if ($playerCount < 3) {
      return;
    }

    $myCards = $player->getCards(IMPROVEMENT, true)->count();
    $otherPlayers = $player->getOtherPlayers();
    $playersWithMoreCards = 0;

    foreach ($otherPlayers as $other) {
      $otherCards = $other->getCards(IMPROVEMENT, true)->count();
      if ($otherCards > $myCards) {
        $playersWithMoreCards++;
      }
    }

    $reduction = 0;
    if ($playersWithMoreCards >= 2) {
      $reduction = 1;
    }
    if ($playersWithMoreCards >= 3) {
      $reduction = 2;
    }
    if ($playersWithMoreCards >= 4) {
      $reduction = 3;
    }

    if ($reduction > 0) {
      Utils::addBonusChoices($args['costs'], [
        [WOOD => -$reduction],
        [CLAY => -$reduction],
        [STONE => -$reduction],
        [REED => -$reduction],
      ], $this->id);
    }
  }

