methods.onPlayerHarvestFieldPhase:
  public function onPlayerHarvestFieldPhase($player, $event = null)
  {
    $groups = $this->getExtraDatas('groups') ?? [];
    $purchased = $this->getExtraDatas('purchased') ?? 0;
    $remaining = [];
    foreach ($groups as $i => $group) {
      $hasAll = true;
      foreach ($group['types'] as $type => $nbr) {
        $onCard = Meeples::getResourcesOnCard($this->id, $player->getId(), $type);
        if ($onCard->count() == 0) {
          $hasAll = false;
          break;
        }
      }
      if ($hasAll) {
        $remaining[] = $i;
      }
    }
    if (empty($remaining)) return null;

    $cost = 2 + $purchased;
    $childs = [];
    foreach ($remaining as $groupIdx) {
      $group = $groups[$groupIdx];
      $receiveChilds = [];
      foreach ($group['types'] as $type => $nbr) {
        $onCard = Meeples::getResourcesOnCard($this->id, $player->getId(), $type);
        $meeple = $onCard->first();
        $meepleId = is_object($meeple) ? $meeple->id : $meeple['id'];
        $receiveChilds[] = $this->receiveNode($meepleId, true, $player);
      }
      $childs[] = [
        'type' => NODE_SEQ,
        'optional' => true,
        'childs' => array_merge(
          [$this->payNode([FOOD => $cost], $this->name, 1, null, $player->getId())],
          $receiveChilds,
          [[
            'action' => SPECIAL_EFFECT,
            'args' => [
              'cardId' => $this->id,
              'method' => 'markPurchased',
              'args' => [],
            ],
          ]]
        ),
      ];
    }
    return [
      'type' => NODE_XOR,
      'optional' => true,
      'childs' => $childs,
    ];
  }

methods.onPlayerAfterCollect:
public function onPlayerAfterCollect($player, $event)
{
  $cards = $this->getPlayer()->getPlayedCards();
  $wood_ = false;
  $clay_ = false;
  $reed_ = false;
  
  foreach ($cards as $card){
    $Id = $card->getId();
    if (in_array($Id, ['Major_Joinery', 'K122_Sawmill'])){
      // $flow = array_merge($flow, [WOOD => 2]);
      $wood_ = true;
    }
    if (in_array($Id, ['Major_Pottery', 'WM086_GlassblowersShop'])){
      // $flow = array_merge($flow, [CLAY => 2]);
      $clay_ = true;
    }
    if (in_array($Id, ['Major_Basket', 'FR041_PeasantsBoutique'])){
      // $flow = array_merge($flow, [REED => 2]);
      $reed_ = true;
    }
  }
  $meeples = $event['meeples'];
  $types = [];
  foreach ($meeples as $meeple) 
    if (!in_array($meeple['type'], $types))
      $types[] = $meeple['type'];
  // print_r($types);
  if (count($types) > 1 || count($types) === 0)
    return;
  else
    {
      if ($types[0] == WOOD && $wood_)
        return $this->gainNode([WOOD => 2]);
      if ($types[0] == CLAY && $clay_)
        return $this->gainNode([CLAY => 2]);
      if ($types[0] == REED && $reed_)
        return $this->gainNode([REED => 1]);
    }
}

