public function actDiscardMinorAndDrawOccupation($cardIds)
{
  $player = $this->getPlayer();
  $cardId = is_array($cardIds) ? reset($cardIds) : $cardIds;

  $minor = $player->getHand(MINOR)
    ->filter(function ($card) use ($cardId) {
      return $card->getId() == $cardId;
    })
    ->first();
  if ($minor == null) {
    throw new \BgaUserException('Invalid card selection');
  }

  // Discard the chosen minor improvement
  PlayerCard::DB()->update(['player_id' => null, 'card_location' => 'trash'], $minor->getId());

  // Draw a random occupation from the deck
  $deck = PlayerCards::getInLocation('box')
    ->filter(function ($card) {
      return $card->getType() == OCCUPATION;
    });
  if ($deck->empty()) {
    return;
  }
  $ids = $deck->getIds();
  PlayerCards::drawCardToHand($ids, $player->getId(), 1, 'hand');

  Notifications::message(
    clienttranslate('${player_name} discards a minor improvement and draws an occupation (${source})'),
    [
      'player' => $player,
      'source' => $this->name,
    ]
  );
}

