methods.onPlayerBeforeEndOfGame:
public function onPlayerBeforeEndOfGame($player, $event)
{
  $borrowed = $this->getExtraDatas('borrowed') ?? 0;
  if ($borrowed <= 0) {
    return null;
  }
  $veggies = $player->countReserveResource(VEGETABLE);
  $canReturn = min($borrowed, $veggies);
  $beggingCards = $borrowed - $canReturn;
  $childs = [];
  if ($canReturn > 0) {
    $childs[] = $this->payNode([VEGETABLE => $canReturn]);
  }
  if ($beggingCards > 0) {
    $childs[] = $this->gainNode([BEGGING_CARD => $beggingCards]);
  }
  if (empty($childs)) {
    return null;
  }
  return ['type' => NODE_SEQ, 'childs' => $childs];
}

