methods.actPlaceResources:
public function actPlaceResources($zones)
{
  $player = $this->getPlayer();
  $freeZones = $player->board()->getFreeZones();

  // Keep only valid and distinct free zones
  $valid = [];
  foreach ($zones as $zone) {
    if ($this->isInZones($freeZones, $zone['x'], $zone['y']) && !$this->isInZones($valid, $zone['x'], $zone['y'])) {
      $valid[] = ['x' => $zone['x'], 'y' => $zone['y']];
    }
  }
  if (count($valid) != 2) {
    throw new \BgaVisibleSystemException('FL039_Cosmographer : exactly 2 distinct free zones are required');
  }

  // First selected zone gets the reed, second one gets the stone
  $meepleIds = Meeples::createResourceInLocation(REED, 'board', $player->getId(), $valid[0]['x'], $valid[0]['y'], 1);
  array_push($meepleIds, ...Meeples::createResourceInLocation(STONE, 'board', $player->getId(), $valid[1]['x'], $valid[1]['y'], 1));

  $this->setExtraDatas('zones', [
    'reed' => $valid[0],
    'stone' => $valid[1],
  ]);

  Notifications::placeMeeple(Meeples::getMany($meepleIds));
}

