methods.actCollectResources:
public function actCollectResources($zones)
{
  $player = $this->getPlayer();
  $placed = $this->getPlacedZones();

  // Exactly one zone holding a placed resource must be selected
  $zone = null;
  foreach ($zones as $z) {
    if ($this->isInZones($placed, $z['x'], $z['y'])) {
      $zone = $z;
      break;
    }
  }
  if ($zone === null) {
    throw new \BgaVisibleSystemException('FL039_Cosmographer : no placed resource on the selected zone');
  }

  $collected = [];
  foreach ($placed as $key => $pos) {
    if ($pos['x'] != $zone['x'] || $pos['y'] != $zone['y']) {
      continue;
    }
    $type = $key == 'reed' ? REED : STONE;
    $meeples = Meeples::getSelectQuery()
      ->wherePlayer($player->getId())
      ->where([['type', $type], ['location', 'board'], ['x', $pos['x']], ['y', $pos['y']]])
      ->get();
    foreach ($meeples as $meeple) {
      Meeples::DB()->update(['meeple_location' => 'reserve'], $meeple['id']);
      $meeple['location'] = 'reserve';
      $collected[] = $meeple;
    }
    unset($placed[$key]);
  }

  $this->setExtraDatas('zones', $placed);

  if (!empty($collected)) {
    Notifications::placeMeeple($collected);
  }
}

methods.computeBonusScore:
public function computeBonusScore()
{
  $player = $this->getPlayer();
  $zones = $this->getPlacedZones();
  $pastures = $player->board()->getPastures();
  $animals = $player->getAnimals('board');
  $bonus = 0;

  $checks = [
    'reed' => SHEEP,
    'stone' => PIG,
  ];
  foreach ($checks as $key => $animalType) {
    if (!isset($zones[$key])) {
      continue;
    }
    $pos = $zones[$key];

    // Paddock holding the placed resource (may be null if not inside any paddock)
    $pastureNodes = null;
    foreach ($pastures as $p) {
      if ($this->isInZones($p['nodes'], $pos['x'], $pos['y'])) {
        $pastureNodes = $p['nodes'];
        break;
      }
    }

    // The animal counts if it shares the paddock with the resource, or if it is on the exact same space
    foreach ($animals as $animal) {
      if ($animal['type'] != $animalType) {
        continue;
      }
      $sameSpace = $animal['x'] == $pos['x'] && $animal['y'] == $pos['y'];
      $samePasture = $pastureNodes !== null && $this->isInZones($pastureNodes, $animal['x'], $animal['y']);
      if ($sameSpace || $samePasture) {
        $bonus += 2;
        break;
      }
    }
  }

  if ($bonus > 0) {
    $this->addBonusScoringEntry($bonus);
  }
}

