public function actAddCropToField($zones)
{
  $player = $this->getPlayer();
  $fields = $this->getPlantedFields($player);

  $field = null;
  foreach ($zones as $picked) {
    foreach ($fields as $valid) {
      if ($valid['uid'] == ($picked['uid'] ?? null)) {
        $field = $valid;
        break 2;
      }
    }
  }

  if (is_null($field) || empty($field['crops'])) {
    throw new \BgaVisibleSystemException('FL042_Rainmaker : the selected zone is not a planted field');
  }

  $type = $field['crops'][0]['type'];
  $location = $field['type'] == 'fieldCard' ? $field['id'] : 'board';

  $ids = Meeples::createResourceInLocation($type, $location, $field['pId'], $field['x'], $field['y'], 1);

  Notifications::sow(
    $player,
    [
      [
        'field' => $field['id'],
        'type' => $type,
        'crops' => Meeples::getMany($ids)->toArray(),
      ],
    ],
    true
  );
  Notifications::updateDropZones($player);
}

