public function onPlayerAtAnytime($player, $event)
{
  $foodOnCard = Meeples::getResourcesOnCard($this->id, $player->getId(), FOOD)->count();
  if ($foodOnCard == 0) {
    return null;
  }
  $options = [['type' => NODE_SEQ, 'childs' => []]];
  $prices = [
    SHEEP => 2, STONE => 2,
    PIG => 3, GRAIN => 3,
    CATTLE => 4, VEGETABLE => 4,
  ];
  foreach ($prices as $type => $cost) {
    if ($foodOnCard >= $cost) {
      $options[] = [
        'type' => NODE_SEQ,
        'childs' => [
          [
            'action' => SPECIAL_EFFECT,
            'args' => [
              'cardId' => $this->id,
              'method' => 'useFoodFromCard',
              'args' => [$cost],
            ],
          ],
          $this->gainNode([$type => 1]),
        ],
      ];
    }
  }
  return ['type' => NODE_XOR, 'optional' => true, 'childs' => $options];
}

