  public function onPlayerStartHarvest($player, $event)
  {
    $pigCount = $player->countReserveResource(PIG);
    $cattleCount = $player->countReserveResource(CATTLE);

    if ($pigCount == 0 && $cattleCount == 0) {
      return null;
    }

    $options = [];

    if ($pigCount > 0) {
      $options[] = [
        'type' => NODE_SEQ,
        'optional' => true,
        'childs' => [
          [
            'action' => SPECIAL_EFFECT,
            'args' => [
              'cardId' => $this->id,
              'method' => 'convertPigToScore',
            ],
          ],
        ],
      ];
    }

    if ($cattleCount > 0) {
      $options[] = [
        'type' => NODE_SEQ,
        'optional' => true,
        'childs' => [
          [
            'action' => SPECIAL_EFFECT,
            'args' => [
              'cardId' => $this->id,
              'method' => 'convertCattleToScore',
            ],
          ],
        ],
      ];
    }

    if (empty($options)) {
      return null;
    }

    return [
      'type' => NODE_OR,
      'optional' => true,
      'childs' => $options,
    ];
  }

