methods.placeFoodOnColumn:
public function placeFoodOnColumn($actionCardId)
{
  $player = $this->getPlayer();
  $usedCard = ActionCards::get($actionCardId);
  if ($usedCard == null) return;
  $column = $usedCard->getBoard();
  $visibleCards = ActionCards::getVisible($player);
  foreach ($visibleCards as $card) {
    if ($card->getId() == $actionCardId) continue;
    if ($card->getBoard() != $column) continue;
    $farmers = Farmers::getOnCard($card->getId());
    $occupied = false;
    foreach ($farmers as $farmer) {
      if ($farmer['state'] == ADULT) {
        $occupied = true;
        break;
      }
    }
    if (!$occupied) {
      $created = Meeples::createResourceInLocation(FOOD, $card->getId(), null, null, null, 1);
      Notifications::accumulate(Meeples::getMany($created), true);
    }
  }
}

