methods.onPlayerAtAnytime:
public function onPlayerAtAnytime($player, $event)
{
  $owner = $this->getPlayer();
  if ($player->getId() != $owner->getId()) {
    return null;
  }
  $opponents = [];
  foreach (Players::getAll() as $p) {
    if ($p->getId() == $owner->getId()) continue;
    $fences = Meeples::getResourcesOnCard('board', $p->getId(), FENCE);
    if ($fences->count() == 0) {
      $opponents[] = $p;
    }
  }
  if (empty($opponents)) {
    return null;
  }
  $ownerFences = $owner->countReserveResource(FENCE);
  if ($ownerFences < count($opponents)) {
    return null;
  }
  $childs = [];
  foreach ($opponents as $opp) {
    $childs[] = [
      'action' => SPECIAL_EFFECT,
      'args' => [
        'cardId' => $this->id,
        'method' => 'giveFenceToPlayer',
        'args' => [$opp->getId()],
      ],
    ];
  }
  return [
    'type' => NODE_XOR,
    'optional' => true,
    'childs' => [
      ['type' => NODE_SEQ, 'childs' => []],
      ['type' => NODE_SEQ, 'childs' => $childs],
    ],
  ];
}

methods.giveFenceToPlayer:
public function giveFenceToPlayer($pId)
{
  $owner = $this->getPlayer();
  $fence = Meeples::getResourcesOnCard('reserve', $owner->getId(), FENCE)->first();
  if ($fence == null) return;
  $board = Players::get($pId)->board();
  $freeZones = $board->getFreeZones(true);
  if (empty($freeZones)) return;
  $zone = reset($freeZones);
  Meeples::DB()->update([
    'meeple_location' => 'board',
    'meeple_player_id' => $pId,
    'meeple_x' => $zone['x'],
    'meeple_y' => $zone['y'],
  ], $fence['id']);
  $fence['location'] = 'board';
  $fence['pId'] = $pId;
  $fence['x'] = $zone['x'];
  $fence['y'] = $zone['y'];
  Notifications::placeMeeple([$fence]);
}

methods.onOpponentAfterCollect:
  public function onOpponentAfterCollect($player, $event)
  {
    $meeples = $event['meeples'] ?? [];
    $nonFoodTypes = [];
    foreach ($meeples as $meeple) {
      if ($meeple['type'] != FOOD && !in_array($meeple['type'], $nonFoodTypes)) {
        $nonFoodTypes[] = $meeple['type'];
      }
    }
    if (empty($nonFoodTypes)) return null;

    $fences = Meeples::getResourcesOnCard('board', $player->getId(), FENCE);
    if ($fences->count() == 0) return null;

    $owner = $this->getPlayer();
    $childs = [
      [
        'action' => SPECIAL_EFFECT,
        'args' => [
          'cardId' => $this->id,
          'method' => 'takeBackFence',
          'args' => [$player->getId()],
