      [
        'type' => NODE_SEQ,
        'pId' => $owner->getId(),
        'childs' => [$this->gainNode([FOOD => 1], $owner->getId())],
      ],
    ];
    foreach ($nonFoodTypes as $type) {
      $childs[] = [
        'type' => NODE_SEQ,
        'pId' => $player->getId(),
        'childs' => [$this->gainNode([$type => 1], $player->getId())],
      ];
    }
    return [
      'type' => NODE_XOR,
      'optional' => true,
      'childs' => [
        ['type' => NODE_SEQ, 'childs' => []],
        ['type' => NODE_SEQ, 'childs' => $childs],
      ],
    ];
  }

