methods.onPlayerComputeCostsConstruct:
public function onPlayerComputeCostsConstruct($player, &$args)
{
  $baseReed = 0;
  foreach ($args['costs']['trades'] as $trade) {
    $baseReed = max($baseReed, $trade[REED] ?? 0);
  }
  // Remember the unmodified reed cost of a room to later count how many reed were replaced
  $this->setExtraDatas('baseReed', $baseReed);

  foreach ($args['costs']['trades'] as $trade) {
    if (($trade[REED] ?? 0) <= 0) {
      continue;
    }
    $maxReplace = min(2, $trade[REED]);
    for ($i = 1; $i <= $maxReplace; $i++) {
      $newTrade = $trade;
      $newTrade[REED] -= $i;
      if ($newTrade[REED] <= 0) {
        unset($newTrade[REED]);
      }
      $newTrade[STONE] = ($newTrade[STONE] ?? 0) + $i;
      $newTrade['sources'][] = $this->id;
      Utils::addCost($args['costs'], $newTrade);
    }
  }
}

