public function onPlayerComputeCostsRenovation($player, &$args)
{
  foreach ($args['costs']['fees'] as $fee) {
    if (($fee[REED] ?? 0) > 0) {
      $newFee = $fee;
      $newFee[REED] -= 1;
      if ($newFee[REED] <= 0) {
        unset($newFee[REED]);
      }
      $newFee[STONE] = ($newFee[STONE] ?? 0) + 1;
      $newFee['sources'][] = $this->id;
      Utils::addFees($args['costs'], $newFee);
    }
  }
}

