    // The food is granted by gainFoodConstruct once the number of rooms built is known
    $this->setExtraDatas('pendingReed', $used ? ($event['cost'][REED] ?? 0) : -1);
    return null;
  }

  if ($source == 'Renovation' && $used) {
    // Exactly 1 reed can be replaced per renovation
    return $this->gainNode([FOOD => 2]);
  }
  return null;
}

