methods.gainFoodConstruct:
public function gainFoodConstruct($nbRooms)
{
  $pendingReed = $this->getExtraDatas('pendingReed');
  $this->setExtraDatas('pendingReed', -1);
  if ($pendingReed === null || $pendingReed < 0) {
    return;
  }

  $replaced = $this->getExtraDatas('baseReed') * $nbRooms - $pendingReed;
  if ($replaced <= 0) {
    return;
  }

  Engine::insertAsChild($this->gainNode([FOOD => 2 * $replaced]));
}

