public function onPlayerStartOfTurn($player, $event = null)
{
  $nPlayers = Players::count();
  $woodThreshold = $nPlayers >= 5 ? 9 : ($nPlayers >= 4 ? 8 : 7);
  $clayThreshold = $nPlayers >= 5 ? 8 : ($nPlayers >= 4 ? 7 : 6);

  $woodCount = 0;
  $woodSpaces = ActionCards::getAccumulationSpaces(WOOD);
  foreach ($woodSpaces as $space) {
    $woodCount += Meeples::getResourcesOnCard($space->getId(), null, WOOD)->count();
  }

  $clayCount = 0;
  $claySpaces = ActionCards::getAccumulationSpaces(CLAY);
  foreach ($claySpaces as $space) {
    $clayCount += Meeples::getResourcesOnCard($space->getId(), null, CLAY)->count();
  }

  $gains = [];
  if ($woodCount >= $woodThreshold) {
    $gains[WOOD] = 1;
  }
  if ($clayCount >= $clayThreshold) {
    $gains[CLAY] = 1;
  }
  if (!empty($gains)) {
    return $this->gainNode($gains);
  }
  return null;
}

