methods.onOpponentAfterCollect:
  public function onOpponentAfterCollect($player, $event)
  {
    $actionCardId = $event['actionCardId'] ?? null;
    if ($actionCardId == null) return null;
    if ($actionCardId != 'ActionTravelingPlayers') return null;
    $count = $this->getExtraDatas('buskerCount') ?? 0;
    $count++;
    $this->setExtraDatas('buskerCount', $count);

    if ($count == 1) {
      $meeple = Meeples::getResourcesOnCard($this->id, $this->pId, FOOD)->first();
      if ($meeple) return $this->receiveNode($meeple['id'], true);
    } elseif ($count == 2) {
      $meeple = Meeples::getResourcesOnCard($this->id, $this->pId, GRAIN)->first();
      if ($meeple) return $this->receiveNode($meeple['id'], true);
    } elseif ($count == 3) {
      $meeples = Meeples::getResourcesOnCard($this->id, $this->pId, FOOD);
      $flow = ['type' => NODE_SEQ, 'childs' => []];
      $n = 0;
      foreach ($meeples as $m) {
        if ($n >= 2) break;
        $flow['childs'][] = $this->receiveNode($m['id'], true);
        $n++;
      }
      return $flow;
    } elseif ($count >= 4) {
      return $this->gainNode([VEGETABLE => 1]);
    }
    return null;
  }

