methods.addCardResourceTrades:
  private function addCardResourceTrades(&$costs, $player)
  {
    $cardCounts = $this->getCardResourceCounts($player);
    $resourceMap = [
      WOOD => self::WOOD_GOODS,
      CLAY => self::CLAY_GOODS,
      REED => self::REED_GOODS,
      STONE => self::STONE_GOODS,
    ];

    $newTrades = [];
    foreach ($costs['trades'] as $trade) {
      foreach ($resourceMap as $regular => $special) {
        if (isset($trade[$regular]) && $trade[$regular] > 0 && $cardCounts[$regular] > 0) {
          $maxReplace = min($trade[$regular], $cardCounts[$regular]);
          for ($i = 1; $i <= $maxReplace; $i++) {
            $copy = $trade;
            $copy[$regular] -= $i;
            if ($copy[$regular] <= 0) {
              unset($copy[$regular]);
            }
            $copy[$special] = $i;
            $copy['sources'][] = $this->id;
            $newTrades[] = $copy;
          }
        }
      }
    }
    foreach ($newTrades as $trade) {
      $costs['trades'][] = $trade;
    }
  }

