methods.onPlayerComputeCardCosts:
  public function onPlayerComputeCardCosts($player, &$args)
  {
    $card = $args['card'] ?? null;
    if ($card == null) return;
    if ($card->getType() != MAJOR) return;

    $values = [FOOD => 1, REED => 1, WOOD => 2, CLAY => 3, STONE => 4];
    $maxAmounts = [];
    foreach ($values as $res => $val) {
      $maxAmounts[$res] = min($player->countReserveResource($res), 14);
    }

    $trades = [];
    for ($food = 0; $food <= $maxAmounts[FOOD]; $food++) {
      for ($reed = 0; $reed <= $maxAmounts[REED]; $reed++) {
        for ($wood = 0; $wood <= $maxAmounts[WOOD]; $wood++) {
          for ($clay = 0; $clay <= $maxAmounts[CLAY]; $clay++) {
            for ($stone = 0; $stone <= $maxAmounts[STONE]; $stone++) {
              $points = $food * 1 + $reed * 1 + $wood * 2 + $clay * 3 + $stone * 4;
              if ($points >= 9 && $points <= 14) {
                $trade = ['sources' => [$this->id], 'max' => 1, 'nb' => 1];
                if ($food > 0) $trade[FOOD] = $food;
                if ($reed > 0) $trade[REED] = $reed;
                if ($wood > 0) $trade[WOOD] = $wood;
                if ($clay > 0) $trade[CLAY] = $clay;
                if ($stone > 0) $trade[STONE] = $stone;
                $trades[] = $trade;
              }
            }
          }
        }
      }
