methods.computeBonusScore:
  public function computeBonusScore()
  {
    $player = $this->getPlayer();
    $board = $player->board();

    $pastures = $board->getPastures();
    foreach ($pastures as $pasture) {
      if (!$this->isRectangle($pasture['nodes'])) {
        return;
      }
    }

    $fields = $board->getFields();
    $fieldNodes = [];
    foreach ($fields as $field) {
      $fieldNodes[] = ['x' => $field['x'], 'y' => $field['y']];
    }
    if (!empty($fieldNodes) && !$this->isRectangle($fieldNodes)) {
      return;
    }

    $this->addBonusScoringEntry(3);
  }

methods.isRectangle:
private function isRectangle($nodes)
{
  if (empty($nodes)) {
    return true;
  }
  $minX = PHP_INT_MAX;
  $maxX = PHP_INT_MIN;
  $minY = PHP_INT_MAX;
  $maxY = PHP_INT_MIN;
  $nodeSet = [];
  foreach ($nodes as $node) {
    $x = $node['x'];
    $y = $node['y'];
    $minX = min($minX, $x);
    $maxX = max($maxX, $x);
    $minY = min($minY, $y);
    $maxY = max($maxY, $y);
    $nodeSet[$x . '_' . $y] = true;
  }
  $expected = ($maxX - $minX + 1) * ($maxY - $minY + 1);
  if (count($nodes) != $expected) {
    return false;
  }
  for ($x = $minX; $x <= $maxX; $x++) {
    for ($y = $minY; $y <= $maxY; $y++) {
      if (!isset($nodeSet[$x . '_' . $y])) {
        return false;
      }
    }
  }
  return true;
}

methods.onPlayerComputeArgsPlaceFarmer:
  public function onPlayerComputeArgsPlaceFarmer($player)
  {
    if ($player->countFarmers() != 4) return [];
    $placedCount = Farmers::getPlacedFarmers($player->getId())->count();
    if ($placedCount != 1) return [];

    $roundCards = ActionCards::getVisible($player)
      ->filter(function ($space) {
        $turn = $space->getTurn() ?? 0;
        return $turn >= 1 && $turn <= 7;
      })
      ->sort(function ($a, $b) {
        return ($a->getTurn() ?? 0) - ($b->getTurn() ?? 0);
      });

    $added = [];
    $cardsArr = iterator_to_array($roundCards);
    for ($i = 0; $i < count($cardsArr); $i++) {
      for ($j = $i + 1; $j < count($cardsArr); $j++) {
        $c1 = $cardsArr[$i];
        $c2 = $cardsArr[$j];
        $t1 = $c1->getTurn() ?? 0;
        $t2 = $c2->getTurn() ?? 0;
        if (abs($t1 - $t2) != 1) continue;
        if (Farmers::getOnCard($c1->getId())->count() > 0) continue;
        if (Farmers::getOnCard($c2->getId())->count() > 0) continue;
        $added[] = [
          'actionCardId' => $c1->getId(),
          'secondActionCardId' => $c2->getId(),
          'playerConstraint' => $player->getId(),
          'ignoreResources' => false,
        ];
      }
    }
    return $added;
  }

