  protected function addAlternativeMaterialBonus(&$args, $count)
  {
    foreach ($args['costs']['trades'] as &$trade) {
      if (isset($trade[WOOD]) && $trade[WOOD] > 0) {
        $maxReplace = min($trade[WOOD], 2 * $count);
        if ($maxReplace >= 2) {
          $newTrade = $trade;
          $newTrade[WOOD] -= 2;
          $newTrade[CLAY] = ($newTrade[CLAY] ?? 0) + 2;
          $args['costs']['trades'][] = $newTrade;

          $newTrade2 = $trade;
          $newTrade2[WOOD] -= 2;
          $newTrade2[STONE] = ($newTrade2[STONE] ?? 0) + 2;
          $args['costs']['trades'][] = $newTrade2;

