    foreach ($zones as $zone) {
      if ($zone['type'] != 'pasture') {
        continue;
      }
      $all ++ ;
      if ($zone['capacity'] - $zone['animals'] == 0) {
        $bonus++;
      }
    }
    if ($all == $bonus && $bonus > 0)
      $bonus += 1;

    if ($bonus != 0) {
      $this->addBonusScoringEntry($bonus);
    }
  }

