methods.onPlayerStartReturnHome:
public function onPlayerStartReturnHome($player, $event)
{
  // Only real, visible board spaces count. A child has not taken an action;
  // temporary guests, on the other hand, explicitly do count.
  $people = Farmers::getAllOfPlayer($player->getId())
    ->merge(Guests::getAllOfPlayer($player->getId()));
  $occupied = [];
  foreach ($people as $person) {
    if ($person['state'] != CHILD) $occupied[$person['location']] = true;
  }
  $groups = [];
  foreach (ActionCards::getVisible() as $space) {
    if (!isset($occupied[$space->getId()])) continue;
    $pos = ActionSpaceLayout::position($space);
    if ($pos === null) continue;
    $groups[$pos['group']][$pos['x'] . ',' . $pos['y']] = $pos;
  }
  $longest = 0;
  foreach ($groups as $coordinates) {
    foreach ($coordinates as $pos) {
      foreach ([[1, 0], [0, 1]] as $direction) {
        $length = 1;
        while (isset($coordinates[($pos['x'] + $length * $direction[0]) . ',' .
            ($pos['y'] + $length * $direction[1])])) $length++;
        $longest = max($longest, $length);
      }
    }
  }
  $score = $longest >= 5 ? 5 : ($longest == 4 ? 3 : ($longest == 3 ? 1 : 0));
  return $score > 0 ? $this->gainNode([SCORE => $score]) : null;
}

