public function onPlayerAfterExchange($player, $event)
{
  $resources = [WOOD, CLAY, REED, STONE, SHEEP, PIG, CATTLE, GRAIN, VEGETABLE];
  $trades = $event['trades'];
  $exchanges = $event['exchanges'];
  $flow = [];
  
  foreach ($trades as $tradeIndex) {
    if (is_array($tradeIndex) && $tradeIndex['source'] == 'discard') {
      continue;
    }
    $exchange = $exchanges[$tradeIndex] ?? null;
    $isfood = $exchange['to'][FOOD] ?? null;
    if (!is_null($isfood)) {
      foreach ($resources as $res) {
        $is_ = $exchange['from'][$res] ?? null;
        if (!is_null($is_) && count(Meeples::getResourcesOnCard($this->id, null, $res)) == 0) {
          $flow[] = [
            'action' => SPECIAL_EFFECT,
            'args' => [
              'cardId' => $this->id,
              'method' => 'addGood',
              'args' => [$res],
            ],
          ];
        }
      }
    }
  }
  
  if (count($flow) == 0) {
    return null;
  }
  
  if (count($flow) == 1) {
    return $flow[0];
  }
  
  return [
    'type' => NODE_PARALLEL,
    'childs' => $flow,
  ];
