  $card = PlayerCards::get($args['card']->getId());
  $costs = $card->getBaseCosts();
  $resources = [WOOD, CLAY, REED, STONE];
  $max_ = 0;
  foreach ($costs as $cost){
    $all_count = 0;
    foreach ($resources as $res){
      if (isset($cost[$res]) && $cost[$res] >= 1) 
        $all_count += $cost[$res];
    }
    if ($max_ < $all_count)
      $max_ = $all_count;
  }
  if ($max_ >= 4)
  Utils::addBonusChoices($args['costs'], [
    [WOOD => -1],
    [CLAY => -1],
    [STONE => -1],
    [REED => -1],
  ], $this->id);
}

