methods.getValidChoices:
  private function getValidChoices()
  {
    $resources = [WOOD, CLAY];
    $playerCount = count(\AGR\Managers\Players::getAll());
    if ($playerCount >= 5) {
      $resources[] = STONE;
    }

    $validResources = [];
    foreach ($resources as $resource) {
      if ($this->hasDuplicateCount($resource)) {
        $validResources[] = ['resource' => $resource];
      }
    }

    return $validResources;
  }

methods.hasDuplicateCount:
  private function hasDuplicateCount($resourceType)
  {
    $actionCards = ActionCards::getVisible();
    $countMap = [];

    foreach ($actionCards as $card) {
      if (!$card->hasAccumulation()) {
        continue;
      }

      $accumulation = $card->getAccumulation();
      if (!isset($accumulation[$resourceType])) {
        continue;
      }

      $location = $card->getLocation();
      $meeples = Meeples::getResourcesOnCard($location, null);
      $count = 0;
      foreach ($meeples as $meeple) {
        if ($meeple['type'] == $resourceType) {
          $count++;
        }
      }

      if ($count > 0) {
        if (!isset($countMap[$count])) {
          $countMap[$count] = 0;
        }
        $countMap[$count]++;
        
        if ($countMap[$count] >= 2) {
          return true;
        }
      }
    }

    return false;
  }

