methods.getExchanges:
public function getExchanges()
{
  $active = $this->getExtraDatas('active');
  $targetPId = $this->getExtraDatas('targetPId');
  if (!$active || !$targetPId) {
    return parent::getExchanges();
  }
  $target = Players::get($targetPId);
  if (!$target) {
    return parent::getExchanges();
  }
  $exchanges = [];
  $impCards = $target->getCards(IMPROVEMENT, true);
  foreach ($impCards as $card) {
    if ($card->getId() == $this->id) continue;
    $exchanges = array_merge($exchanges, $card->getExchanges());
  }
  return $exchanges;
}

