  public function onPlayerAfterGain($player, $event)
  {
    $actionCardId = $event['actionCardId'] ?? null;
    $cards = array_column(ActionCards::getVisible($player) -> toArray(), 'id');
    if (!in_array($actionCardId, $cards))
      return;

    $all_type = [WOOD, CLAY, REED, STONE];
    $meeples = $event['meeples'];
    $found_type = [];
    $get = $this->getExtraDatas('get');
    foreach ($meeples as $meeple) {
      if (!in_array($meeple['type'], $found_type) && in_array($meeple['type'], $all_type)) {
        $found_type[] = $meeple['type'];
      }
    }
    if (($player->getId() == $this->pId) && (count(Farmers::getAllAvailable($player->getId())) + count(Guests::getAllAvailable($player->getId()))) == 0)
    {
      $flow = [];
      foreach($found_type as $type){
        if (!$get[$type]) 
        {
          $flow[] = $this->gainNode([$type => 1]);
          $get[$type] = True;
        }
      }
      // print_r(count($flow));
      // $this->setExtraDatas('get', $get);
      if (count($flow) > 0)
        return ['type' => NODE_SEQ, 
          'childs' => [
            [
              'action' => SPECIAL_EFFECT,
              'args' => [
                          'cardId' => $this->id,
                          'method' => 'Setget',
                          'args' => [$get]
                        ]
            ],
            ['type' => NODE_XOR, 'optional' => true, 'childs' => $flow]]
        ];
    }
    else
    {
      foreach($found_type as $type){
        if (!$get[$type]) $get[$type] = true;
      }
      // $this->setExtraDatas('get', $get);
      return [
              'action' => SPECIAL_EFFECT,
              'args' => [
                          'cardId' => $this->id,
                          'method' => 'Setget',
                          'args' => [$get]
                        ]
            ];
    }
  }

