methods.buyStone:
  public function buyStone()
  {
    $actionCardId = $this->getExtraDatas('actionCardId');
    if (empty($actionCardId)) {
      return;
    }

    $foodOnFishing = Meeples::getResourcesOnCard($actionCardId, null, FOOD);
    if ($foodOnFishing->count() < 2) {
      return;
    }

    for ($i = 0; $i < 2; $i++) {
      $food = $foodOnFishing->shift();
      Meeples::destroy($food['id']);
    }

    $player = $this->getPlayer();
    $created = Meeples::createResourceInReserve($player->getId(), STONE, 1);
    Notifications::gain(Meeples::getMany($created));
  }

