methods.getAvailableWoodSpaces:
  protected function getAvailableWoodSpaces()
  {
    $woodActionCards = ['ActionForest', 'ActionGrove', 'ActionCopse', 'ActionCopseAdd', 'ActionForestSolo'];
    $available = [];

    foreach ($woodActionCards as $cardId) {
      $card = ActionCards::get($cardId);
      if ($card && !$card->isOccupied()) {
        $available[] = $cardId;
      }
    }

    return $available;
  }

