methods.actG046_PondWatchman:
  public function actG046_PondWatchman($args)
  {
    $player = $this->getPlayer();
    $farmerId = $args['farmerId'];
    $woodSpaceId = $args['woodSpaceId'];

    if ($player->countResource(FOOD) < 1) {
      throw new \BgaVisibleSystemException(clienttranslate('Not enough food'));
    }

    $player->useResource(FOOD, 1);

    Meeples::moveToCoords($farmerId, $woodSpaceId);

    $woodResources = Meeples::collectResourcesOnCard($player, $woodSpaceId);
    if (!empty($woodResources)) {
      Notifications::collectResources($player, $woodResources);
    }

    $woodCard = ActionCards::get($woodSpaceId);
    Notifications::placeFarmer($player, ['id' => $farmerId], $woodCard);

    $this->resolveAction();
  }

