  public function onPlayerAfterGain($player, $event)
  {
    $actionCardId = $event['actionCardId'] ?? null;
    $cards = array_column(ActionCards::getVisible($player) -> toArray(), 'id');
    if (!in_array($actionCardId, $cards))
      return;

    $has_stone = false;
    $meeples = $event['meeples'];
    foreach ($meeples as $meeple) {
      if ($meeple['type'] == STONE)
        $has_stone = true;
    }
    if ($has_stone)
    {
      // $cards = Improvement::getBuyableCards($player);
      $ids = ['Major_Joinery','Major_Pottery','Major_StoneOven','Major_Well','Major_Basket','Major_ClayOven'];
      $cards_im = $player->getHand(MINOR);
      foreach($cards_im as $card)
      {
        $costs = $card->getBaseCosts();
        foreach ($costs as $cost)
          if (isset($cost[STONE]) && $cost[STONE] >= 1) 
          {
            $ids[] = $card->getId();
            break;
          }
      }
      // $cards_maj = 
      return 
      [
        'type' => NODE_SEQ, 'optional' => true, 'childs' => [
            $this->payNode([FOOD => 1]),
                  Utils::wrapOptional([      
                'action' => IMPROVEMENT,
                'optional' => false,
                'pId' => $event['pId'],
                'args' => [
                  'types' => [MINOR, MAJOR],
                  'trueAction' => false,
                  'allowedCards' => $ids
                ],
                ])
              ]
              ];
    }
  }

methods.onPlayerComputeCostsFencing:
  public function onPlayerComputeCostsFencing($player, &$args)
  {
    if (!empty($args['costs']['constraints'] ?? [])) {
      return;
    }
    $trades = [];
    foreach ($args['costs']['trades'] as $trade) {
      $keys = array_diff(array_keys($trade), ['nb', 'max']);

      if ($keys == [WOOD]) {
        $trade[STONE] = $trade[WOOD];
        $trade['nb'] = 2;
        unset($trade[WOOD]);
        $trades[] = $trade;
        
      }
    }
    foreach($trades as $trade)
      Utils::addCost($args['costs'], $trade);
  }

