    }

    $this->setExtraDatas('actionCardId', $actionCardId);

    return [
      'type' => NODE_SEQ,
      'childs' => [
        [
          'type' => NODE_XOR,
          'optional' => true,
          'childs' => [
            [
              'action' => PLACE_FARMER,
              'pId' => $this->pId,
              'args' => [
