methods.onPlayerAfterExchange:
public function onPlayerAfterExchange($player, $event)
{
  $trades = $event['trades'];
  $exchanges = $event['exchanges'];
  $eated = 0;
  foreach ($trades as $tradeIndex) {
    if (is_array($tradeIndex) && $tradeIndex['source'] == 'discard') {
      continue;
    }
    $exchange = $exchanges[$tradeIndex] ?? null;
    // print_r($exchange);
    if ($exchange) {
      $isveg = $exchange['from'][VEGETABLE] ?? null;
      $isgrain = $exchange['from'][GRAIN] ?? null;
      if (!is_null($isveg) || !is_null($isgrain)){
        $isfood = $exchange['to'][FOOD] ?? null;
        if (!is_null($isfood))
          $eated += 1;
      }
      $issheep = $exchange['from'][SHEEP] ?? null;
      $ispig = $exchange['from'][PIG] ?? null;
      $iscattle = $exchange['from'][CATTLE] ?? null;
      if (!is_null($issheep) || !is_null($ispig) || !is_null($iscattle)){
        $isfood = $exchange['to'][FOOD] ?? null;
        if (!is_null($isfood))
          throw new \BgaUserException('You are not allowed to eat animals (素食主义者)');
      }        
    }
  }
  // print_r($eated);
  if ($eated > 0)
  return $this->gainNode([FOOD => $eated]);
}

