methods.onOpponentAfterCollect:
public function onOpponentAfterCollect($player, $event)
{
  $delayedTypes = [WOOD, CLAY, REED, STONE, GRAIN, VEGETABLE, SHEEP, PIG, CATTLE];
  $gained = $event['gain'] ?? [];
  $toDelay = [];
  foreach ($delayedTypes as $type) {
    if (isset($gained[$type]) && $gained[$type] > 0) {
      $toDelay[$type] = $gained[$type];
    }
  }
  if (empty($toDelay)) return null;
  $delayed = Globals::get('Z329_delayed_' . $player->getId()) ?? [];
  foreach ($toDelay as $type => $amount) {
    $delayed[$type] = ($delayed[$type] ?? 0) + $amount;
  }
  Globals::set('Z329_delayed_' . $player->getId(), $delayed);
  return $this->payNode($toDelay);
}

methods.onPlayerEndWorkPhase:
public function onPlayerEndWorkPhase($player, $event = null)
{
  $flow = ['type' => NODE_PARALLEL, 'childs' => []];
  $allPlayers = \AGR\Managers\Players::getAll();
  foreach ($allPlayers as $opp) {
    if ($opp->getId() == $player->getId()) continue;
    $delayed = Globals::get('Z329_delayed_' . $opp->getId()) ?? [];
    if (!empty($delayed)) {
      $flow['childs'][] = $this->gainNodeFor($opp->getId(), $delayed);
      Globals::set('Z329_delayed_' . $opp->getId(), []);
    }
  }
  if (!empty($flow['childs'])) {
    return $flow;
  }
  return null;
}

