methods.getTargetSpaces:
protected function getTargetSpaces()
{
  $spaces = [];
  $allCards = ActionCards::getVisible();
  foreach ($allCards as $card) {
    $type = $card->getActionCardType();
    if ($type == 'Fishing' || $type == 'DayLaborer' || $type == 'ReedBank') {
      $spaces[] = $card->getId();
    } elseif ($card->getTurn() == 4) {
      $spaces[] = $card->getId();
    }
  }
  return $spaces;
}

methods.onPlayerStartOfTurn:
  public function onPlayerStartOfTurn($player, $event)
  {
    $cardOwner = $this->getPlayer();
    $allPlayers = Players::getAll();
    $playersWithoutFood = [];

    foreach ($allPlayers as $p) {
      if ($p->getId() === $cardOwner->getId()) {
        continue;
      }
      $reserve = $p->getAllReserveResources();
      $food = $reserve[FOOD] ?? 0;
      if ($food === 0) {
        $playersWithoutFood[] = $p->getId();
      }
    }

    if (empty($playersWithoutFood)) {
      return null;
    }

    $ownerReserve = $cardOwner->getAllReserveResources();
    $ownerFood = $ownerReserve[FOOD] ?? 0;
    if ($ownerFood < 1) {
      return null;
    }

    $flow = [];
    foreach ($playersWithoutFood as $targetPId) {
      $targetPlayer = Players::get($targetPId);
      $flow[] = [
        'type' => NODE_SEQ,
        'optional' => true,
        'customDescription' => clienttranslate('给予<FOOD>给 ${player_name} 并获得奖励', ['player_name' => $targetPlayer->getName()]),
        'childs' => [
          $this->payNode([FOOD => 1], null, 1, $cardOwner->getId(), $targetPId),
          $this->getRewardChoice(),
        ],
      ];
    }

    return [
      'type' => NODE_XOR,
      'optional' => true,
      'customDescription' => clienttranslate('选择一位没有<FOOD>的玩家给予1份<FOOD>'),
      'childs' => $flow,
    ];
  }

