  public function onPlayerEndHarvestFieldPhase($player)
  {
    $allPlayers = Players::getAll();
    $foodToGain = 0;

    foreach ($allPlayers as $otherPlayer) {
      if ($otherPlayer->getId() === $this->pId) {
        continue;
      }

      $reserve = $otherPlayer->countAnimalsOnBoard();
      $sheep = $reserve[SHEEP] ?? 0;
      $cattle = $reserve[CATTLE] ?? 0;

      if ($sheep >= 1) {
        $foodToGain += 0.5;
      }
      if ($cattle >= 1) {
        $foodToGain += 1;
      }
    }

    $foodToGain = ceil($foodToGain);

    if ($foodToGain <= 0) {
      return null;
    }

    return $this->gainNode([FOOD => $foodToGain]);
  }

