methods.checkAndConvert:
  protected function checkAndConvert($player, $event)
  {
    $actionCardId = $event['actionCardId'] ?? null;
    if ($actionCardId == null) {
      return null;
    }
    // print_r($actionCardId);
    $actionCard = ActionCards::get($actionCardId);
    if (!$actionCard->hasAccumulation()) {
      return null;
    }

    $meeples = $event['meeples'] ?? [];
    $convertible = [];
    $type_get = [];
    foreach ($meeples as $meeple) {
      $type = $meeple['type'] ?? null;
      if (isset($this->conversionMap[$type]) && !in_array($type, $type_get)) {
        $convertible[] = $this->payGainNode([$type => 1], [$this->conversionMap[$type] => 1]);
        $type_get[] = $type;
      }
    }

    if (empty($convertible)) {
      return null;
    }

    return [
      'type' => NODE_XOR,
      'optional' => true,
      'customDescription' => clienttranslate('将1个物品转换成对应物品'),
      'childs' => $convertible,
    ];
  }

