methods.onPlayerComputeArgsPlaceFarmer:
  public function onPlayerComputeArgsPlaceFarmer($player)
  {
    if (!$this->isFlagged()) {
      return [];
    }

    $added = [];
    $actionCards = ActionCards::getVisible($player);
    
    foreach ($actionCards as $actionCard) {
      $farmers = Farmers::getOnCard($actionCard->getId());
      $guests = Guests::getOnCard($actionCard->getId());
      
      if ($farmers->count() > 0 || $guests->count() > 0) {
        $hasOwnFarmer = false;
        foreach ($farmers as $farmer) {
          if ($farmer['pId'] == $player->getId()) {
            $hasOwnFarmer = true;
            break;
          }
        }
        
        foreach ($guests as $guest) {
          if ($guest['pId'] == $player->getId()) {
            $hasOwnFarmer = true;
            break;
          }
        }
        
        if (!$hasOwnFarmer) {
          $added[] = [
            'actionCardId' => $actionCard->getId(),
            'playerConstraint' => $this->pId,
            'ignoreResources' => false
          ];
        }
      }
    }

    return $added;
  }

methods.onPlayerStartHarvestFieldPhase:
public function onPlayerStartHarvestFieldPhase($player, $event)
{
  if (Globals::getTurn() >= 14){
    $rooms = 0;
    foreach ($player->board()->getRooms() as $room) {
      if ($room['type'] == 'roomStone' ) {
        $rooms += 1;
      }
    }
    $cattles = $player->countAnimalsOnBoard()[CATTLE];
    $nums = $rooms * $cattles;
    $cost = $player->getHarvestCost();
    // $food_get = $nums > $cost ? $cost : $nums;
    $vp_get = $nums > $cost ? $nums - $cost : 0;
    $vp_get = $vp_get > 5 ? 5 : $vp_get;
    $flow = [];
    // if ($food_get > 0){
    //   $flow[] = $this->gainNode([FOOD => $nums]);
    // }
    if ($nums > 0){
      $flow[] = $this->gainNode([FOOD => $nums]);
    }
    if ($vp_get > 0){
      $flow[] = $this->gainNode([SCORE => $vp_get]);
    }
    if (count($flow) > 0){
      return [
        'type' => NODE_SEQ,
        'childs' => $flow
      ];
  }
  }
}

