function topResoucesUsed($event)
{
  if (isset($event['cost'])) {
    $cost = $event['cost'];
    if (isset($cost['bonusChoiceIndex'])) {
      $indexes = $cost['bonusChoiceIndex'];
      if (isset($indexes[$this->id])) {
        return $indexes[$this->id] + 1;
      }
    }
  }
  return 0;
}

