methods.onPlayerPlaceFarmer:
  public function onPlayerPlaceFarmer($player, $event)
  {
    $cardOwner = $this->getPlayer();
    $cardOwnerId = $cardOwner->getId();
    $actorId = $player->getId();

    if ($cardOwnerId == $actorId) {
      return null;
    }

    $turnOrder = Players::getTurnOrder();
    $position = array_search($actorId, $turnOrder);

    if ($position === false) {
      return null;
    }

    $rewards = [
      0 => [VEGETABLE => 1],
      1 => [SHEEP => 1],
      2 => [STONE => 1],
      3 => [SCORE => 1],
    ];

    $reward = $rewards[$position] ?? null;

    if ($reward === null) {
      return null;
    }

    return $this->gainNode($reward, $cardOwnerId);
  }

