  public function onPlayerComputeArgsPlaceFarmer($player)
  {
    $currentTurn = Globals::getTurn();
    
    if ($currentTurn < 13) {
      return [];
    }

    $location = ['turn', 13];
    $cards = ActionCards::getInLocation($location);

    $added = [];
    foreach ($cards as $card) {
      $cardId = $card->getId();
      
      $farmersOnCard = Farmers::getOnCard($cardId);
      if ($farmersOnCard->empty()) {
        continue;
      }

      $ownerOccupied = false;
      foreach ($farmersOnCard as $farmer) {
        if ($farmer['player_id'] == $player->getId()) {
          $ownerOccupied = true;
          break;
        }
      }

      if (!$ownerOccupied) {
        $added[] = [
          'actionCardId' => $cardId,
          'playerConstraint' => 'dummy',
          'ignoreResources' => false,
        ];
      }
    }

    return $added;
  }

