  protected function checkAndGainWood($player, $event)
  {
    $meeples = $event['meeples'] ?? [];
    $woodCount = 0;

    foreach ($meeples as $meeple) {
      if ($meeple['type'] === WOOD) {
        $woodCount++;
      }
    }

    if ($woodCount < 1 || $woodCount > 3) {
      return null;
    }

    $actionCardId = $event['actionCardId'] ?? null;
    if ($actionCardId == null) {
      return null;
    }

    if (!in_array($actionCardId, $this->woodActionCards)) {
      return null;
    }

    $cardOwner = $this->getPlayer();
    return [
      'type' => NODE_SEQ,
      'pId' => $cardOwner->getId(),
      'childs' => [
        $this->gainNode([WOOD => 1]),
