methods.checkAnimalGain:
protected function checkAnimalGain($player, $event)
{
  $meeples = $event['meeples'] ?? [];
  $animalCounts = [SHEEP => 0, PIG => 0, CATTLE => 0];
  foreach ($meeples as $meeple) {
    $type = $meeple['type'] ?? null;
    if (isset($animalCounts[$type])) {
      $animalCounts[$type]++;
    }
  }
  $qualifiedAnimals = [];
  foreach ($animalCounts as $animal => $count) {
    if ($count >= 2) {
      $qualifiedAnimals[] = $animal;
    }
  }
  if (empty($qualifiedAnimals)) {
    return null;
  }
  $opponentId = $event['pId'] ?? $player->getId();
  $choices = [];
  foreach ($qualifiedAnimals as $animal) {
    $foodCost = $this->animalCosts[$animal];
    $choices[] = [
      'type' => NODE_SEQ,
      'childs' => [
        $this->payNode([FOOD => $foodCost], null, 1, $opponentId),
        [
          'action' => SPECIAL_EFFECT,
          'args' => [
            'cardId' => $this->id,
            'method' => 'takeAnimalFromOpponent',
            'args' => [$opponentId, $animal],
          ],
        ],
        $this->gainNode([$animal => 1]),
      ],
    ];
  }
  return [
    'type' => NODE_XOR,
    'optional' => true,
    'pId' => $this->getPlayer()->getId(),
    'childs' => $choices,
  ];
}

