methods.onPlayerComputeCardCosts:
public function onPlayerComputeCardCosts($player, &$args)
{
  $other_res = [CLAY, REED, STONE];
  $pos_trade = [];
  foreach ($args['costs']['trades'] as $trade) {
    foreach ($other_res as $res)
    {
      if (isset($trade[$res])){
        $trade[$res] -= 1;
        if (!isset($trade[WOOD]))
          $trade[WOOD] = 0;
        $trade[WOOD] += 1;
        // Utils::addCost($args['costs'], $trade);
        $pos_trade[] = $trade;
        $trade[WOOD] -= 1;
        $trade[$res] += 1;
      }
    }
  }
  foreach ($pos_trade as $trade)
    Utils::addCost($args['costs'], $trade);
}

