methods.computeBonusScore:
  public function computeBonusScore()
  {
    $maxResources = 0;
    $winners = [];

    foreach (Players::getAll() as $player) {
      if (!$player->isZombie()) {
        $resources = $player->countReserveResource(WOOD) +
                     $player->countReserveResource(CLAY) +
                     $player->countReserveResource(STONE) +
                     $player->countReserveResource(REED);
        
        if ($resources > $maxResources) {
          $maxResources = $resources;
          $winners = [$player->getId()];
        } elseif ($resources == $maxResources && $resources > 0) {
          $winners[] = $player->getId();
        }
      }
    }

    if (in_array($this->pId, $winners) && $maxResources > 0) {
      $this->addBonusScoringEntry(3);
    }
  }

