            'cardId' => $this->id,
            'method' => 'borrowOccupation',
            'args' => [$occ->getId()],
          ],
        ],
      ],
    ];
  }
  return [
    'type' => NODE_XOR,
    'optional' => true,
    'childs' => $choices,
  ];
}

