  $actionCardId = $event['actionCardId'] ?? null;
  if (empty($actionCardId)) { return null; }
  $cards = ActionCards::getVisible($player);
  $isReused = false;
  foreach ($cards as $card) {
    if ($card->getId() == $actionCardId) {
      $farmersOnCard = Farmers::getOnCard($actionCardId);
      if ($farmersOnCard->count() == 2) {
        $isReused = true;
      }
      break;
    }
  }
  if ($isReused && !$this->getExtraDatas('usedThisRound', false)) {
    $this->setExtraDatas('usedThisRound', true);
    $food = Meeples::getResourcesOnCard($this->id, null, FOOD)->first();
    if ($food) {
      Meeples::DB()->delete($food['id']);
      Notifications::silentKill([$food]);
    }
  }
  return null;
}

