methods.onBuy:
public function onBuy($player)
{
  $childCounts = [];
  foreach (Players::getAll() as $p) {
    $children = Farmers::qPlayer($p->getId(), 'board')->where('meeple_state', CHILD)->count() + Farmers::qPlayer($p->getId(), 'board')->where('meeple_state', ADULT)->count() - 2;
    $childCounts[$p->getId()] = $children;
  }
  $total = array_sum($childCounts);
  $food = min($total, 6);
  $minChildren = min($childCounts);

  $flow = [];
  if ($food > 0) {
    $flow[] = $this->gainNode([FOOD => $food]);
  }
  foreach ($childCounts as $pId => $cnt) {
    if ($cnt == $minChildren) {
      $flow[] = [
        'type' => NODE_SEQ,
        'pId' => $pId,
        'childs' => [
          $this->gainNode([VEGETABLE => 1], $pId),
        ],
      ];
    }
  }
  if (empty($flow)) {
    return null;
  }
  return ['type' => NODE_PARALLEL, 'childs' => $flow];
}

